use super::models::*;
use super::DbPool;
use anyhow::Result;
use rusqlite::OptionalExtension;
use std::collections::{BTreeMap, HashMap};

/// Pozyskuje polaczenie z puli (writer pod pelne read+write).
fn acquire(pool: &DbPool) -> Result<parking_lot::MutexGuard<'_, rusqlite::Connection>> {
    pool.write()
        .map_err(|e| anyhow::anyhow!("Blad blokady bazy: {}", e))
}

/// Public connection handle for the baseline-adopt path, which drives its whole
/// snapshot/import inside a single externally-managed transaction.
///
/// HOLD IT LIGHTLY. This is `acquire`, i.e. the one process-wide writer mutex,
/// and `parking_lot::Mutex` is not reentrant: calling any other `repository`
/// function that takes `pool` while this guard is alive blocks the caller on a
/// lock it already owns (observed in this file's own consumer: a test that
/// still held a baseline guard read `bus_topic_get` and hung until the process
/// was killed). Keep the guard to the transaction it exists for.
pub fn acquire_for_baseline(
    pool: &DbPool,
) -> Result<parking_lot::MutexGuard<'_, rusqlite::Connection>> {
    acquire(pool)
}

#[cfg(test)]
mod core_sync_repository_tests {
    use super::*;
    use crate::sync::core_capture::load_core_write_capture;
    use crate::sync::ledger::FieldValue;
    use crate::sync::runtime::SqlWriteAction;
    use std::path::Path;

    fn setup_db() -> DbPool {
        crate::db::init(Path::new(":memory:")).expect("test db")
    }

    fn flow_params<'a>(
        name: &'a str,
        flow_json: &'a str,
        actor_user_id: Option<&'a str>,
    ) -> FlowParams<'a> {
        FlowParams {
            name,
            description: Some("opis"),
            is_default: false,
            service_type: Some("chat"),
            flow_json,
            status: "active",
            published_model_name: None,
            actor_user_id,
        }
    }

    fn capture_id_for_resource_str(db: &DbPool, resource_type: &str, resource_id: &str) -> String {
        let conn = db.read().expect("db lock");
        conn.query_row(
            "SELECT capture_id FROM __tentaflow_core_sync_captures \
             WHERE resource_type = ?1 AND resource_id = ?2 \
             ORDER BY created_at_ms DESC LIMIT 1",
            rusqlite::params![resource_type, resource_id],
            |row| row.get(0),
        )
        .expect("capture id")
    }

    fn capture_id_for_action(
        db: &DbPool,
        resource_type: &str,
        resource_id: &str,
        action: &str,
    ) -> String {
        let conn = db.read().expect("db lock");
        conn.query_row(
            "SELECT capture_id FROM __tentaflow_core_sync_captures \
             WHERE resource_type = ?1 AND resource_id = ?2 AND action = ?3 \
             ORDER BY created_at_ms DESC LIMIT 1",
            rusqlite::params![resource_type, resource_id, action],
            |row| row.get(0),
        )
        .expect("capture id")
    }

    fn create_actor(db: &DbPool) -> String {
        create_user_account(
            db,
            "flow-owner",
            "hash",
            "Flow Owner",
            "flow-owner@example.com",
        )
        .expect("create actor")
    }

    #[test]
    fn create_flow_records_binary_core_capture() {
        let db = setup_db();
        let _actor_id = create_actor(&db);
        let id =
            create_flow(&db, &flow_params("Flow A", r#"{"nodes":[]}"#, None)).expect("create flow");
        let capture_id = capture_id_for_resource_str(&db, "core.flow", &id);
        let conn = db.read().expect("db lock");
        let capture = load_core_write_capture(&conn, &capture_id)
            .expect("load capture")
            .expect("capture");

        assert_eq!(capture.action, SqlWriteAction::Insert);
        assert_eq!(
            capture.changed_fields.get("name"),
            Some(&FieldValue::String("Flow A".to_string()))
        );
    }

    #[test]
    fn update_flow_with_snapshot_records_flow_and_version_captures() {
        let db = setup_db();
        let _actor_id = create_actor(&db);
        let id =
            create_flow(&db, &flow_params("Flow A", r#"{"nodes":[]}"#, None)).expect("create flow");
        update_flow_with_snapshot(
            &db,
            &id,
            1,
            &flow_params("Flow B", r#"{"nodes":[{"id":"n1"}]}"#, None),
            None,
        )
        .expect("update flow");
        let conn = db.read().expect("db lock");
        let flow_count: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM __tentaflow_core_sync_captures \
                 WHERE resource_type = 'core.flow' AND resource_id = ?1",
                rusqlite::params![id],
                |row| row.get(0),
            )
            .expect("flow capture count");
        // flow_versions now replicate, so the snapshot insert emits one Insert
        // capture alongside the two flow writes (insert + update).
        let version_count: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM __tentaflow_core_sync_captures \
                 WHERE resource_type = 'core.flow_version'",
                [],
                |row| row.get(0),
            )
            .expect("version capture count");
        let local_version_rows: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM flow_versions WHERE flow_id = ?1",
                rusqlite::params![id],
                |row| row.get(0),
            )
            .expect("local version rows");

        assert_eq!(flow_count, 2);
        assert_eq!(version_count, 1);
        assert_eq!(local_version_rows, 1);
    }

    #[test]
    fn create_user_account_records_capture_without_password_hash() {
        let db = setup_db();
        let user_id = create_user_account(
            &db,
            "sales-user",
            "secret-hash",
            "Sales User",
            "sales@example.com",
        )
        .expect("create user");
        let capture_id = capture_id_for_resource_str(&db, "core.user_account", &user_id);
        let conn = db.read().expect("db lock");
        let capture = load_core_write_capture(&conn, &capture_id)
            .expect("load capture")
            .expect("capture");

        assert_eq!(capture.action, SqlWriteAction::Insert);
        assert_eq!(
            capture.changed_fields.get("username"),
            Some(&FieldValue::String("sales-user".to_string()))
        );
        assert!(!capture.changed_fields.contains_key("password_hash"));
    }

    #[test]
    fn password_update_records_only_redacted_capture() {
        let db = setup_db();
        let user_id = create_user_account(
            &db,
            "password-user",
            "old-hash",
            "Password User",
            "password@example.com",
        )
        .expect("create user");
        update_user_account_password(&db, &user_id, "new-secret-hash").expect("update password");
        let capture_id = capture_id_for_action(&db, "core.user_account", &user_id, "update");
        let conn = db.read().expect("db lock");
        let capture = load_core_write_capture(&conn, &capture_id)
            .expect("load capture")
            .expect("capture");

        assert_eq!(capture.action, SqlWriteAction::Update);
        assert_eq!(
            capture.changed_fields.get("password_changed"),
            Some(&FieldValue::Bool(true))
        );
        assert!(!capture.changed_fields.contains_key("password_hash"));
    }

    #[test]
    fn group_membership_records_core_capture() {
        let db = setup_db();
        let user_id =
            create_user_account(&db, "group-user", "hash", "Group User", "group@example.com")
                .expect("create user");
        let group_id = create_group(&db, "Sales", "CRM team").expect("create group");
        add_user_to_group(&db, &group_id, &user_id).expect("add member");
        let resource_id = group_member_resource_id(&group_id, &user_id);
        let capture_id = capture_id_for_resource_str(&db, "core.group_member", &resource_id);
        let conn = db.read().expect("db lock");
        let capture = load_core_write_capture(&conn, &capture_id)
            .expect("load capture")
            .expect("capture");

        assert_eq!(capture.action, SqlWriteAction::Insert);
        assert_eq!(
            capture.changed_fields.get("group_id"),
            Some(&FieldValue::String(group_id.clone()))
        );
        assert_eq!(
            capture.changed_fields.get("user_id"),
            Some(&FieldValue::String(user_id.clone()))
        );
    }

    #[test]
    fn sync_permission_epoch_changes_for_acl_and_role_not_password() {
        let db = setup_db();
        let user_id =
            create_user_account(&db, "epoch-user", "hash", "Epoch User", "epoch@example.com")
                .expect("create user");
        let initial =
            get_sync_permission_epoch(&db, crate::services::org::DEFAULT_ORG_ID).expect("epoch");

        update_user_account_password(&db, &user_id, "new-hash").expect("password");
        let after_password =
            get_sync_permission_epoch(&db, crate::services::org::DEFAULT_ORG_ID).expect("epoch");
        assert_eq!(after_password, initial);

        set_user_role(&db, &user_id, "admin").expect("role");
        let after_role =
            get_sync_permission_epoch(&db, crate::services::org::DEFAULT_ORG_ID).expect("epoch");
        assert!(after_role > after_password);

        upsert_sync_resource_acl(
            &db,
            crate::services::org::DEFAULT_ORG_ID,
            crate::sync::core_registry::CORE_SYNC_ADDON_ID,
            "core.flow",
            "flow-epoch",
            Some(&user_id),
            Some(&user_id),
            None,
            None,
            "assigned",
        )
        .expect("acl");
        let after_acl =
            get_sync_permission_epoch(&db, crate::services::org::DEFAULT_ORG_ID).expect("epoch");
        assert!(after_acl > after_role);
    }
}

