/// Settings key holding the API key pepper (hex, stored encrypted). Replicated as
/// a shared secret (`SHARED_SECRET_SETTING_KEYS`) so it is ORG-WIDE: a key issued
/// on one node verifies on every node because all nodes derive the verifier under
/// the same pepper.
const API_KEY_PEPPER_KEY: &str = "api_key_pepper";

/// Returns the org-wide API key pepper, decrypting the stored value, and only
/// generating + persisting 32 CSPRNG bytes when none exists yet.
///
/// INVARIANT: the pepper is org-wide. A fresh joiner adopts the org's pepper from
/// the baseline snapshot (it travels as a shared secret, re-encrypted per node)
/// BEFORE it ever creates or verifies a key, so this function finds the synced
/// pepper and never mints a divergent one. Generation here is the genesis path:
/// the very first node of an org, or a unit test with an isolated DB.
///
/// RESIDUAL RISK: a full node compromise leaks the org's pepper (not just one
/// node's). RACE: two nodes that each generate a pepper before they sync would
/// derive verifiers under different peppers; convergence then follows the shared-
/// secret LWW (one pepper wins) and keys issued under the loser stop verifying.
/// Mesh E2E (slice 8) validates that the baseline delivers the pepper before any
/// key write, which keeps a freshly joined node out of this race in practice.
pub fn get_or_create_api_key_pepper(
    pool: &DbPool,
    cipher: &crate::crypto::SettingsCipher,
) -> Result<Vec<u8>> {
    fn read_valid_pepper(
        pool: &DbPool,
        cipher: &crate::crypto::SettingsCipher,
    ) -> Result<Option<Vec<u8>>> {
        let Some(hex) = get_setting_secure(pool, API_KEY_PEPPER_KEY, cipher)? else {
            return Ok(None);
        };
        // Fail-closed: a stored pepper that does not decode to EXACTLY 32 bytes
        // is corrupt. Silently accepting it (or auto-rotating it) would either
        // weaken the HMAC key or invalidate every previously issued key without
        // an operator decision, so we refuse instead.
        let bytes = decode_hex(&hex)
            .map_err(|e| anyhow::anyhow!("stored api_key_pepper is not valid hex: {}", e))?;
        if bytes.len() != 32 {
            anyhow::bail!(
                "stored api_key_pepper must decode to exactly 32 bytes, got {}",
                bytes.len()
            );
        }
        Ok(Some(bytes))
    }

    // Fast path: pepper already present.
    if let Some(bytes) = read_valid_pepper(pool, cipher)? {
        return Ok(bytes);
    }
    // Genesis path is serialized in-process so two concurrent callers cannot each
    // generate and persist a different pepper (the loser's keys would stop
    // verifying). Re-check under the lock — another thread may have just created
    // it. Cross-node divergence is a separate, documented case resolved by the
    // shared-secret LWW.
    static PEPPER_GENESIS_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    let _genesis = PEPPER_GENESIS_LOCK
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if let Some(bytes) = read_valid_pepper(pool, cipher)? {
        return Ok(bytes);
    }
    let mut pepper = [0u8; 32];
    getrandom::fill(&mut pepper).expect("OS RNG fill_bytes");
    let mut hex = String::with_capacity(pepper.len() * 2);
    for b in pepper.iter() {
        use std::fmt::Write as _;
        let _ = write!(hex, "{:02x}", b);
    }
    // Persist through the shared-secret path: encrypts with the local cipher AND
    // emits a `core.shared_setting_secret` capture, so a genesis-node pepper also
    // replicates to already-joined peers (joiners get it from the baseline).
    set_shared_secret_setting_secure(pool, API_KEY_PEPPER_KEY, &hex, cipher, None)?;
    Ok(pepper.to_vec())
}

fn decode_hex(s: &str) -> Result<Vec<u8>> {
    if s.len() % 2 != 0 {
        anyhow::bail!("odd-length hex string");
    }
    (0..s.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| anyhow::anyhow!("invalid hex: {}", e))
        })
        .collect()
}

/// Lists keys for the dashboard. The verifier is never returned on lists.
pub fn list_api_keys(pool: &DbPool) -> Result<Vec<DbApiKey>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT id, uid, key_prefix, name, key_type, subject_id, rate_limit_rps, \
                is_active, created_at, last_used_at \
         FROM api_keys ORDER BY name",
    )?;
    let keys = stmt
        .query_map([], |row| {
            Ok(DbApiKey {
                id: row.get(0)?,
                uid: row.get(1)?,
                key_verifier: String::new(),
                key_prefix: row.get(2)?,
                name: row.get(3)?,
                key_type: row.get(4)?,
                subject_id: row.get(5)?,
                rate_limit_rps: row.get(6)?,
                is_active: row.get(7)?,
                created_at: row.get(8)?,
                last_used_at: row.get(9)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(keys)
}

/// Inserts a key with a freshly generated stable `uid`. Returns `(id, uid)`.
pub fn create_api_key(
    pool: &DbPool,
    key_verifier: &str,
    key_prefix: &str,
    name: &str,
    key_type: &str,
    subject_id: Option<&str>,
    rate_limit_rps: i64,
) -> Result<(i64, String)> {
    // Fail-closed: a 'user' key without a subject is anonymous and would bypass
    // per-user ACL on the /v1 surface (None subject is treated as internal).
    if key_type == "user" && subject_id.is_none() {
        anyhow::bail!("api key with key_type='user' requires a subject_id");
    }
    let uid = uuid::Uuid::new_v4().to_string();
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    tx.execute(
        "INSERT INTO api_keys (uid, key_verifier, key_prefix, name, key_type, subject_id, rate_limit_rps) \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
        rusqlite::params![
            uid,
            key_verifier,
            key_prefix,
            name,
            key_type,
            subject_id,
            rate_limit_rps
        ],
    )?;
    let row_id = tx.last_insert_rowid();
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::ApiKey,
        uid.clone(),
        crate::sync::runtime::SqlWriteAction::Insert,
        api_key_changed_fields(
            key_verifier,
            key_prefix,
            name,
            key_type,
            subject_id,
            rate_limit_rps,
            true,
        ),
        None,
    )?;
    tx.commit()?;
    Ok((row_id, uid))
}

/// Atomically creates an API key and (for `general` keys) seeds its explicit
/// `resource_permissions` allowlist in ONE transaction. Either the key and all of
/// its scopes commit together, or nothing does — a scope failure rolls back the
/// key, so callers can never observe a half-created key with a partial allowlist.
///
/// `scopes` are `(resource_type, resource_id)` pairs, each written as an `allow`
/// rule with `subject_type='api_key'`, `subject_id=<new key uid>`. The audit entry
/// is written in the same transaction so it can never be orphaned from the key.
#[allow(clippy::too_many_arguments)]
pub fn create_api_key_with_scopes(
    pool: &DbPool,
    key_verifier: &str,
    key_prefix: &str,
    name: &str,
    key_type: &str,
    subject_id: Option<&str>,
    rate_limit_rps: i64,
    scopes: &[(String, String)],
    actor_user_id: Option<&str>,
    node_id: Option<&str>,
) -> Result<(i64, String)> {
    if key_type == "user" && subject_id.is_none() {
        anyhow::bail!("api key with key_type='user' requires a subject_id");
    }
    if key_type != "general" && !scopes.is_empty() {
        anyhow::bail!("scopes are only valid for key_type='general'");
    }
    let uid = uuid::Uuid::new_v4().to_string();
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    tx.execute(
        "INSERT INTO api_keys (uid, key_verifier, key_prefix, name, key_type, subject_id, rate_limit_rps) \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
        rusqlite::params![
            uid,
            key_verifier,
            key_prefix,
            name,
            key_type,
            subject_id,
            rate_limit_rps
        ],
    )?;
    let row_id = tx.last_insert_rowid();
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::ApiKey,
        uid.clone(),
        crate::sync::runtime::SqlWriteAction::Insert,
        api_key_changed_fields(
            key_verifier,
            key_prefix,
            name,
            key_type,
            subject_id,
            rate_limit_rps,
            true,
        ),
        None,
    )?;
    for (resource_type, resource_id) in scopes {
        resource_permissions::set_tx(&tx, resource_type, resource_id, "api_key", &uid, "allow")?;
    }
    log_audit_tx(
        &tx,
        actor_user_id,
        None,
        "apikey.create",
        Some(&format!("apikey:{}", row_id)),
        Some(&format!("{} ({})", name, key_type)),
        None,
        node_id,
    )?;
    tx.commit()?;
    Ok((row_id, uid))
}

/// Deletes a key by its stable `uid`. Revocation is keyed by `uid` because the
/// 24-bit `key_prefix` is display-only and can collide across keys.
pub fn delete_api_key_by_uid(pool: &DbPool, uid: &str) -> Result<usize> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let affected = tx.execute(
        "DELETE FROM api_keys WHERE uid = ?1",
        rusqlite::params![uid],
    )?;
    if affected > 0 {
        record_core_capture_tx(
            &tx,
            crate::sync::core_registry::CoreSyncResourceKind::ApiKey,
            uid.to_string(),
            crate::sync::runtime::SqlWriteAction::Delete,
            BTreeMap::new(),
            None,
        )?;
    }
    tx.commit()?;
    Ok(affected)
}

pub fn get_api_key_by_uid(pool: &DbPool, uid: &str) -> Result<Option<DbApiKey>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(&format!(
        "SELECT {} FROM api_keys WHERE uid = ?1",
        API_KEY_COLS
    ))?;
    let result = stmt
        .query_row(rusqlite::params![uid], row_to_api_key)
        .optional()?;
    Ok(result)
}

/// Replaces the verifier and prefix for a key identified by `uid` (rotation).
pub fn rotate_api_key(
    pool: &DbPool,
    uid: &str,
    new_verifier: &str,
    new_prefix: &str,
) -> Result<bool> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let affected = tx.execute(
        "UPDATE api_keys SET key_verifier = ?2, key_prefix = ?3 WHERE uid = ?1",
        rusqlite::params![uid, new_verifier, new_prefix],
    )?;
    if affected > 0 {
        // Replicate as a full-row Update: the materializer applies it as an
        // upsert (it needs every synced column), and `last_used_at` stays local.
        record_api_key_full_row_capture_tx(&tx, uid)?;
    }
    tx.commit()?;
    Ok(affected > 0)
}

pub fn set_api_key_active(pool: &DbPool, uid: &str, active: bool) -> Result<bool> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let affected = tx.execute(
        "UPDATE api_keys SET is_active = ?2 WHERE uid = ?1",
        rusqlite::params![uid, active as i64],
    )?;
    if affected > 0 {
        record_api_key_full_row_capture_tx(&tx, uid)?;
    }
    tx.commit()?;
    Ok(affected > 0)
}

/// Records a full-row `core.api_key` Update capture by reading the post-write row
/// inside the same transaction. Partial captures cannot be used: the materializer
/// upserts the whole replicated column set, so every synced field must be present.
fn record_api_key_full_row_capture_tx(tx: &rusqlite::Transaction<'_>, uid: &str) -> Result<()> {
    let row = tx
        .query_row(
            "SELECT key_verifier, key_prefix, name, key_type, subject_id, rate_limit_rps, is_active \
             FROM api_keys WHERE uid = ?1",
            rusqlite::params![uid],
            |r| {
                Ok((
                    r.get::<_, String>(0)?,
                    r.get::<_, String>(1)?,
                    r.get::<_, String>(2)?,
                    r.get::<_, String>(3)?,
                    r.get::<_, Option<String>>(4)?,
                    r.get::<_, i64>(5)?,
                    r.get::<_, bool>(6)?,
                ))
            },
        )
        .optional()?;
    let Some((key_verifier, key_prefix, name, key_type, subject_id, rate_limit_rps, is_active)) =
        row
    else {
        return Ok(());
    };
    record_core_capture_tx(
        tx,
        crate::sync::core_registry::CoreSyncResourceKind::ApiKey,
        uid.to_string(),
        crate::sync::runtime::SqlWriteAction::Update,
        api_key_changed_fields(
            &key_verifier,
            &key_prefix,
            &name,
            &key_type,
            subject_id.as_deref(),
            rate_limit_rps,
            is_active,
        ),
        None,
    )
}

/// Verifies an API key by its precomputed verifier and stamps `last_used_at` on
/// a hit. Inactive keys are never returned.
pub fn verify_api_key(pool: &DbPool, key_verifier: &str) -> Result<Option<DbApiKey>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(&format!(
        "SELECT {} FROM api_keys WHERE key_verifier = ?1 AND is_active = 1",
        API_KEY_COLS
    ))?;
    let result = stmt
        .query_row(rusqlite::params![key_verifier], row_to_api_key)
        .optional()?;
    if let Some(ref key) = result {
        // Throttle the write-on-read: under a shared Arc<Mutex<Connection>> a
        // stamp on every request would serialize verification. Only refresh
        // when the row was never used or last used more than 60s ago, keyed by
        // the indexed primary key.
        conn.execute(
            "UPDATE api_keys SET last_used_at = datetime('now') \
             WHERE id = ?1 \
               AND (last_used_at IS NULL \
                    OR last_used_at < datetime('now','-60 seconds'))",
            rusqlite::params![key.id],
        )?;
    }
    Ok(result)
}

// --- Settings ---

pub fn get_setting(pool: &DbPool, key: &str) -> Result<Option<String>> {
    let conn = acquire(pool)?;
    let result = conn
        .query_row(
            "SELECT value FROM settings WHERE key = ?1",
            rusqlite::params![key],
            |row| row.get(0),
        )
        .optional()?;
    Ok(result)
}

pub fn set_setting(pool: &DbPool, key: &str, value: &str) -> Result<()> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    set_setting_tx(&tx, key, value)?;
    tx.commit()?;
    Ok(())
}

/// Transaction-scoped core of `set_setting`, for a caller that already holds
/// an open write transaction on `pool` (e.g. `config_bundle::apply_bundle`)
/// and must not re-acquire the pool's connection — `DbPool::write()` is a
/// plain, non-reentrant `Mutex`, so calling `set_setting(pool, ..)` mid-
/// transaction on the same thread would self-deadlock.
pub fn set_setting_tx(tx: &rusqlite::Transaction<'_>, key: &str, value: &str) -> Result<()> {
    tx.execute(
        "INSERT INTO settings (key, value) VALUES (?1, ?2) ON CONFLICT(key) DO UPDATE SET value = ?2, updated_at = datetime('now')",
        rusqlite::params![key, value],
    )?;
    // Replicate fleet-wide non-secret settings (allowlist only). Same resource
    // kind as shared secrets; the apply path branches secret vs plaintext by key.
    // Gated to the 8 allowlisted keys, so node-local/internal settings written
    // through this same chokepoint never leave the node.
    if is_shared_setting_key(key) {
        record_core_capture_tx(
            tx,
            crate::sync::core_registry::CoreSyncResourceKind::SharedSettingSecret,
            key,
            crate::sync::runtime::SqlWriteAction::Update,
            shared_secret_setting_fields(key, value),
            None,
        )?;
    }
    Ok(())
}

/// Returns just the org ids. Used by the sync backfill pre-gate, which must
/// enumerate orgs WITHOUT a full ledger scan to compare permission epochs.
pub fn list_all_org_ids(pool: &DbPool) -> Result<Vec<String>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare("SELECT org_id FROM organizations ORDER BY org_id ASC")?;
    let ids = stmt
        .query_map([], |row| row.get::<_, String>(0))?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(ids)
}

fn sync_permission_epoch_key(org_id: &str) -> String {
    format!("sync.permission_epoch:{org_id}")
}

fn bump_sync_permission_epoch_with_conn(conn: &rusqlite::Connection, org_id: &str) -> Result<u64> {
    let key = sync_permission_epoch_key(org_id);
    conn.execute(
        "INSERT INTO settings (key, value) VALUES (?1, '1') \
         ON CONFLICT(key) DO UPDATE SET \
             value = CAST(CAST(value AS INTEGER) + 1 AS TEXT), \
             updated_at = datetime('now')",
        rusqlite::params![key],
    )?;
    read_sync_permission_epoch_with_conn(conn, org_id)
}

fn read_sync_permission_epoch_with_conn(conn: &rusqlite::Connection, org_id: &str) -> Result<u64> {
    let key = sync_permission_epoch_key(org_id);
    let value = conn
        .query_row(
            "SELECT value FROM settings WHERE key = ?1",
            rusqlite::params![key],
            |row| row.get::<_, String>(0),
        )
        .optional()?
        .unwrap_or_else(|| "0".to_string());
    value
        .parse::<u64>()
        .map_err(|e| anyhow::anyhow!("Nieprawidlowa epoka permissions sync: {}", e))
}

pub fn bump_sync_permission_epoch(pool: &DbPool, org_id: &str) -> Result<u64> {
    let conn = acquire(pool)?;
    bump_sync_permission_epoch_with_conn(&conn, org_id)
}

pub fn get_sync_permission_epoch(pool: &DbPool, org_id: &str) -> Result<u64> {
    let conn = acquire(pool)?;
    read_sync_permission_epoch_with_conn(&conn, org_id)
}

/// Odczytuje setting z automatycznym deszyfrowaniem (jesli klucz jest wrazliwy)
pub fn get_setting_secure(
    pool: &DbPool,
    key: &str,
    cipher: &crate::crypto::SettingsCipher,
) -> Result<Option<String>> {
    let raw = get_setting(pool, key)?;
    match raw {
        Some(val) if crate::crypto::SettingsCipher::should_encrypt(key) => Ok(Some(
            cipher.decrypt(&val).map_err(|e| anyhow::anyhow!("{}", e))?,
        )),
        other => Ok(other),
    }
}

/// Zapisuje setting z automatycznym szyfrowaniem (jesli klucz jest wrazliwy)
pub fn set_setting_secure(
    pool: &DbPool,
    key: &str,
    value: &str,
    cipher: &crate::crypto::SettingsCipher,
) -> Result<()> {
    if crate::crypto::SettingsCipher::should_encrypt(key) {
        let encrypted = cipher
            .encrypt(value)
            .map_err(|e| anyhow::anyhow!("{}", e))?;
        set_setting(pool, key, &encrypted)
    } else {
        set_setting(pool, key, value)
    }
}

/// Allowlist of `settings` keys that replicate as `core.shared_setting_secret`
/// (re-encrypted per node). Single source of truth for the secret capture path,
/// the upgrade-time enqueue, and the baseline-reset reseed.
pub const SHARED_SECRET_SETTING_KEYS: &[&str] = &["hf_token", "ngc_api_key", "api_key_pepper"];

pub fn is_shared_secret_setting_key(key: &str) -> bool {
    SHARED_SECRET_SETTING_KEYS.contains(&key)
}

/// Allowlist of NON-secret `settings` keys that replicate fleet-wide (stored
/// plaintext, no re-encrypt). Deny-by-default: only genuinely shareable
/// admin/fleet config is here. Node-local keys (node_*_key, jwt_secret,
/// encryption_master_key, mesh.bind_* / advertise_excluded_interfaces — physical
/// interface specific, mesh.bind_mode — coupled to bind_ipv4) and internal sync
/// state (baseline_*, sync.permission_epoch:*) are deliberately EXCLUDED and
/// must never be added here. Replicated through the same SharedSettingSecret
/// resource kind (the apply path branches secret vs non-secret by key).
pub const SHARED_SETTING_KEYS: &[&str] = &[
    "mesh.iroh_relay_url",
    "mesh.advertise_hide_docker",
    "mesh.advertise_hide_link_local",
    "mesh.advertise_hide_loopback",
    "mesh.advertise_hide_cgnat",
    "mesh.advertise_prefer_same_subnet",
    "oauth_redirect_base_url",
    "jwt_expiry_hours",
];

pub fn is_shared_setting_key(key: &str) -> bool {
    SHARED_SETTING_KEYS.contains(&key)
}

fn shared_secret_setting_fields(
    key: &str,
    value: &str,
) -> BTreeMap<String, crate::sync::ledger::FieldValue> {
    let mut fields = BTreeMap::new();
    fields.insert("key".to_string(), field_string(key));
    fields.insert("value".to_string(), field_string(value));
    fields
}

pub fn set_shared_secret_setting_secure(
    pool: &DbPool,
    key: &str,
    value: &str,
    cipher: &crate::crypto::SettingsCipher,
    actor_user_id: Option<&str>,
) -> Result<()> {
    if !is_shared_secret_setting_key(key) {
        anyhow::bail!("setting nie jest syncowalnym sekretem: {}", key);
    }
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let encrypted = cipher
        .encrypt(value)
        .map_err(|e| anyhow::anyhow!("{}", e))?;
    tx.execute(
        "INSERT INTO settings (key, value) VALUES (?1, ?2) \
         ON CONFLICT(key) DO UPDATE SET value = ?2, updated_at = datetime('now')",
        rusqlite::params![key, encrypted],
    )?;
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::SharedSettingSecret,
        key,
        crate::sync::runtime::SqlWriteAction::Update,
        shared_secret_setting_fields(key, value),
        actor_user_id.map(|id| id.to_string()),
    )?;
    tx.commit()?;
    Ok(())
}

pub fn enqueue_existing_shared_secret_settings(
    pool: &DbPool,
    cipher: &crate::crypto::SettingsCipher,
) -> Result<usize> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let mut count = 0usize;
    for &key in SHARED_SECRET_SETTING_KEYS {
        let raw: Option<String> = tx
            .query_row(
                "SELECT value FROM settings WHERE key = ?1",
                rusqlite::params![key],
                |row| row.get(0),
            )
            .optional()?;
        let Some(raw_value) = raw else {
            continue;
        };
        if raw_value.is_empty() {
            continue;
        }
        let existing: i64 = tx.query_row(
            "SELECT COUNT(*) FROM __tentaflow_core_sync_captures \
             WHERE resource_type = 'core.shared_setting_secret' AND resource_id = ?1",
            rusqlite::params![key],
            |row| row.get(0),
        )?;
        if existing > 0 {
            continue;
        }
        let value = cipher
            .decrypt(&raw_value)
            .map_err(|e| anyhow::anyhow!("{}", e))?;
        record_core_capture_tx(
            &tx,
            crate::sync::core_registry::CoreSyncResourceKind::SharedSettingSecret,
            key,
            crate::sync::runtime::SqlWriteAction::Update,
            shared_secret_setting_fields(key, &value),
            None,
        )?;
        count += 1;
    }
    tx.commit()?;
    Ok(count)
}

/// Usuwa ustawienie po kluczu (CR-016: jednorazowe tokeny SSO state)
pub fn delete_setting(pool: &DbPool, key: &str) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "DELETE FROM settings WHERE key = ?1",
        rusqlite::params![key],
    )?;
    Ok(())
}

pub fn list_settings(pool: &DbPool) -> Result<Vec<DbSetting>> {
    let conn = acquire(pool)?;
    let mut stmt =
        conn.prepare_cached("SELECT key, value, updated_at FROM settings ORDER BY key")?;
    let settings = stmt
        .query_map([], |row| {
            Ok(DbSetting {
                key: row.get(0)?,
                value: row.get(1)?,
                updated_at: row.get(2)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(settings)
}

/// Zwraca pary `(key, value)` ze `settings` ktorych klucz zaczyna sie od `prefix`.
/// Uzywane m.in. przez `net::iroh::pairing::sanitize_trusted_contacts` do iteracji
/// po wpisach `trusted_contact:*` bez wczytywania calej tabeli.
pub fn list_settings_with_prefix(pool: &DbPool, prefix: &str) -> Result<Vec<(String, String)>> {
    let conn = acquire(pool)?;
    let pattern = format!("{}%", prefix);
    let mut stmt = conn.prepare_cached(
        "SELECT key, value FROM settings WHERE key LIKE ?1 ESCAPE '\\' ORDER BY key",
    )?;
    let rows = stmt
        .query_map(rusqlite::params![pattern], |row| {
            let key: String = row.get(0)?;
            let value: String = row.get(1)?;
            Ok((key, value))
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

/// Lista jezykow akceptowanych w `user_accounts.preferred_language` i w polu
/// `language` requestu TTS. Trzymana w jednym miejscu, bo walidacja zapisu
/// preferencji i walidacja body'ego endpointu musza wzajemnie sie zgadzac.
pub const SUPPORTED_USER_LANGUAGES: &[&str] = &["pl", "en", "fr", "es", "de"];

/// Zwraca preferowany jezyk uzytkownika lub None jesli brak preferencji.
pub fn get_user_preferred_language(pool: &DbPool, user_id: &str) -> Result<Option<String>> {
    let conn = acquire(pool)?;
    let result = conn
        .query_row(
            "SELECT preferred_language FROM user_accounts WHERE id = ?1",
            rusqlite::params![user_id],
            |row| row.get::<_, Option<String>>(0),
        )
        .optional()?
        .flatten();
    Ok(result)
}

/// Ustawia preferowany jezyk uzytkownika. `lang = None` czysci preferencje.
/// Zwraca blad gdy `lang` nie nalezy do `SUPPORTED_USER_LANGUAGES`.
pub fn set_user_preferred_language(pool: &DbPool, user_id: &str, lang: Option<&str>) -> Result<()> {
    if let Some(code) = lang {
        if !SUPPORTED_USER_LANGUAGES.contains(&code) {
            return Err(anyhow::anyhow!(
                "Nieobslugiwany kod jezyka: '{}' (dozwolone: {:?})",
                code,
                SUPPORTED_USER_LANGUAGES
            ));
        }
    }
    let conn = acquire(pool)?;
    conn.execute(
        "UPDATE user_accounts SET preferred_language = ?1 WHERE id = ?2",
        rusqlite::params![lang, user_id],
    )?;
    Ok(())
}

