/// Discovery view for the addon-facing `alias_list_available_v1` host function:
/// every `[[uses_alias]]` declaration of `addon_id` joined LEFT with the
/// resolved `model_aliases` row and its visibility. A LEFT join is deliberate —
/// a declaration whose owner addon is not installed yet stays `pending` with no
/// alias row, and the addon should still see it (honest pending state) rather
/// than have it silently vanish. `methods` is decoded from the JSON-array column
/// written at owner-install time; a malformed/empty value yields an empty list.
pub fn list_addon_available_aliases(
    pool: &DbPool,
    addon_id: &str,
) -> Result<Vec<DbAvailableAlias>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT u.alias_target_name, u.required, u.grant_status, \
                a.target_model, a.strategy, a.is_active, a.methods, v.visibility \
         FROM addon_uses_alias u \
         LEFT JOIN model_aliases a ON a.alias = u.alias_target_name \
         LEFT JOIN model_alias_visibility v ON v.alias_id = a.id \
         WHERE u.addon_id = ?1 \
         ORDER BY u.alias_target_name",
    )?;
    let rows = stmt
        .query_map(rusqlite::params![addon_id], |r| {
            let methods_json: Option<String> = r.get(6)?;
            let active: Option<i64> = r.get(5)?;
            Ok(DbAvailableAlias {
                alias_id: r.get(0)?,
                required: r.get::<_, i64>(1)? != 0,
                grant_status: r.get(2)?,
                target_model: r.get(3)?,
                strategy: r.get(4)?,
                active: active.unwrap_or(0) != 0,
                methods: methods_json
                    .and_then(|s| serde_json::from_str::<Vec<String>>(&s).ok())
                    .unwrap_or_default(),
                visibility: r.get(7)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

// ---- Pool-level orchestration (mutation + reconcile + audit in one tx) ------
// Each entrypoint runs the privileged change, reconciles dependent
// `addon_uses_*` rows, and writes both the per-transition audit rows and the
// change-log row inside a single transaction so the dashboard can never read a
// half-applied state.

/// Sets model visibility, reconciles dependent `addon_uses_model`, and records
/// the change. Returns the list of `(addon_id, before, after)` transitions.
#[allow(clippy::type_complexity)]
pub fn set_model_visibility_audited(
    pool: &DbPool,
    model_id: &str,
    visibility: &str,
    user_id: Option<i64>,
) -> Result<Vec<(String, String, String)>> {
    if visibility != "restricted" && visibility != "public" {
        anyhow::bail!("model visibility must be 'restricted' or 'public'");
    }
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let before = lookup_model_visibility_within_tx(&tx, model_id)?;
    set_model_visibility_within_tx(&tx, model_id, visibility, user_id)?;
    let transitions = reconcile_uses_model_for_model_within_tx(&tx, model_id)?;
    for (addon, b, a) in &transitions {
        audit_reconcile_uses_model_within_tx(&tx, addon, model_id, b, a)?;
    }
    let before_snap = serde_json::json!({ "visibility": before }).to_string();
    let after_snap = serde_json::json!({ "visibility": visibility }).to_string();
    record_model_visibility_change_within_tx(
        &tx,
        model_id,
        user_id,
        None,
        Some(&before_snap),
        Some(&after_snap),
        "visibility_change",
        None,
    )?;
    tx.commit()?;
    Ok(transitions)
}

/// Grants a model consumer, reconciles, and records the change.
#[allow(clippy::type_complexity)]
pub fn grant_model_consumer_audited(
    pool: &DbPool,
    model_id: &str,
    consumer_addon_id: &str,
    user_id: Option<i64>,
) -> Result<Vec<(String, String, String)>> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    add_model_consumer_within_tx(&tx, model_id, consumer_addon_id, user_id)?;
    let transitions = reconcile_uses_model_for_model_within_tx(&tx, model_id)?;
    for (addon, b, a) in &transitions {
        audit_reconcile_uses_model_within_tx(&tx, addon, model_id, b, a)?;
    }
    let after_snap =
        serde_json::json!({ "consumer": consumer_addon_id, "state": "granted" }).to_string();
    record_model_visibility_change_within_tx(
        &tx,
        model_id,
        user_id,
        Some(consumer_addon_id),
        None,
        Some(&after_snap),
        "consumer_grant",
        None,
    )?;
    tx.commit()?;
    Ok(transitions)
}

/// Revokes a model consumer (soft delete), reconciles, and records the change.
#[allow(clippy::type_complexity)]
pub fn revoke_model_consumer_audited(
    pool: &DbPool,
    model_id: &str,
    consumer_addon_id: &str,
    user_id: Option<i64>,
) -> Result<Vec<(String, String, String)>> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    revoke_model_consumer_within_tx(&tx, model_id, consumer_addon_id)?;
    let transitions = reconcile_uses_model_for_model_within_tx(&tx, model_id)?;
    for (addon, b, a) in &transitions {
        audit_reconcile_uses_model_within_tx(&tx, addon, model_id, b, a)?;
    }
    let after_snap =
        serde_json::json!({ "consumer": consumer_addon_id, "state": "revoked" }).to_string();
    record_model_visibility_change_within_tx(
        &tx,
        model_id,
        user_id,
        Some(consumer_addon_id),
        None,
        Some(&after_snap),
        "consumer_revoke",
        None,
    )?;
    tx.commit()?;
    Ok(transitions)
}

/// Sets alias visibility (by alias id), reconciles dependent
/// `addon_uses_alias`, and writes one audit row per transition plus the alias
/// change-log row. Returns `(addon_id, before, after)` transitions.
#[allow(clippy::type_complexity)]
pub fn set_alias_visibility_audited(
    pool: &DbPool,
    alias_id: i64,
    visibility: &str,
    user_id: Option<i64>,
) -> Result<Vec<(String, String, String)>> {
    if !matches!(visibility, "private" | "restricted" | "public") {
        anyhow::bail!("alias visibility must be 'private', 'restricted' or 'public'");
    }
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let alias_name: String = tx
        .query_row(
            "SELECT alias FROM model_aliases WHERE id = ?1",
            rusqlite::params![alias_id],
            |r| r.get(0),
        )
        .optional()?
        .ok_or_else(|| anyhow::anyhow!("alias id {} not found", alias_id))?;
    let before = tx
        .query_row(
            "SELECT visibility FROM model_alias_visibility WHERE alias_id = ?1",
            rusqlite::params![alias_id],
            |r| r.get::<_, String>(0),
        )
        .optional()?
        .unwrap_or_else(|| "private".to_string());
    set_alias_visibility_within_tx(&tx, alias_id, visibility, user_id)?;
    let transitions = reconcile_uses_alias_for_alias_within_tx(&tx, &alias_name)?;
    for (addon, b, a) in &transitions {
        audit_reconcile_uses_alias_within_tx(&tx, addon, &alias_name, b, a)?;
    }
    let before_snap = serde_json::json!({ "visibility": before }).to_string();
    let after_snap = serde_json::json!({ "visibility": visibility }).to_string();
    tx.execute(
        "INSERT INTO model_alias_changes \
            (alias_id, alias_name, changed_by_user_id, before_snapshot, after_snapshot, change_type, ts) \
         VALUES (?1, ?2, ?3, ?4, ?5, 'suggested_default_change', strftime('%s','now'))",
        rusqlite::params![alias_id, alias_name, user_id, before_snap, after_snap],
    )?;
    tx.commit()?;
    Ok(transitions)
}

/// Grants an alias consumer (by alias id), reconciles, and records the change.
#[allow(clippy::type_complexity)]
pub fn grant_alias_consumer_audited(
    pool: &DbPool,
    alias_id: i64,
    consumer_addon_id: &str,
    user_id: Option<i64>,
) -> Result<Vec<(String, String, String)>> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let alias_name: String = tx
        .query_row(
            "SELECT alias FROM model_aliases WHERE id = ?1",
            rusqlite::params![alias_id],
            |r| r.get(0),
        )
        .optional()?
        .ok_or_else(|| anyhow::anyhow!("alias id {} not found", alias_id))?;
    add_alias_consumer_within_tx(&tx, alias_id, consumer_addon_id, user_id)?;
    let transitions = reconcile_uses_alias_for_alias_within_tx(&tx, &alias_name)?;
    for (addon, b, a) in &transitions {
        audit_reconcile_uses_alias_within_tx(&tx, addon, &alias_name, b, a)?;
    }
    let after_snap =
        serde_json::json!({ "consumer": consumer_addon_id, "state": "granted" }).to_string();
    tx.execute(
        "INSERT INTO model_alias_changes \
            (alias_id, alias_name, changed_by_user_id, after_snapshot, change_type, ts) \
         VALUES (?1, ?2, ?3, ?4, 'suggested_default_change', strftime('%s','now'))",
        rusqlite::params![alias_id, alias_name, user_id, after_snap],
    )?;
    tx.commit()?;
    Ok(transitions)
}

/// Revokes an alias consumer (soft delete by alias id), reconciles, records.
#[allow(clippy::type_complexity)]
pub fn revoke_alias_consumer_audited(
    pool: &DbPool,
    alias_id: i64,
    consumer_addon_id: &str,
    user_id: Option<i64>,
) -> Result<Vec<(String, String, String)>> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let alias_name: String = tx
        .query_row(
            "SELECT alias FROM model_aliases WHERE id = ?1",
            rusqlite::params![alias_id],
            |r| r.get(0),
        )
        .optional()?
        .ok_or_else(|| anyhow::anyhow!("alias id {} not found", alias_id))?;
    tx.execute(
        "UPDATE model_alias_consumers \
            SET revoked_at = strftime('%s','now') \
          WHERE alias_id = ?1 AND consumer_addon_id = ?2 AND revoked_at IS NULL",
        rusqlite::params![alias_id, consumer_addon_id],
    )?;
    let transitions = reconcile_uses_alias_for_alias_within_tx(&tx, &alias_name)?;
    for (addon, b, a) in &transitions {
        audit_reconcile_uses_alias_within_tx(&tx, addon, &alias_name, b, a)?;
    }
    let after_snap =
        serde_json::json!({ "consumer": consumer_addon_id, "state": "revoked" }).to_string();
    tx.execute(
        "INSERT INTO model_alias_changes \
            (alias_id, alias_name, changed_by_user_id, after_snapshot, change_type, ts) \
         VALUES (?1, ?2, ?3, ?4, 'suggested_default_change', strftime('%s','now'))",
        rusqlite::params![alias_id, alias_name, user_id, after_snap],
    )?;
    tx.commit()?;
    Ok(transitions)
}

/// Raw insert into `model_aliases` — bypasses chain check, JSON validation,
/// alias-name collision. Available **only** in test builds so product code
/// physically cannot reach it. Tests use it to seed known-CSV / known-empty
/// rows that drive the migration / chain-guard tests.
#[cfg(test)]
fn create_model_alias_unchecked(
    pool: &DbPool,
    alias: &str,
    target_model: &str,
    fallback_targets: Option<&str>,
    strategy: Option<&str>,
) -> Result<i64> {
    let conn = acquire(pool)?;
    conn.execute(
        "INSERT INTO model_aliases (alias, target_model, fallback_targets, strategy) VALUES (?1, ?2, ?3, ?4)",
        rusqlite::params![alias, target_model, fallback_targets, strategy.unwrap_or("first_available")],
    )?;
    Ok(conn.last_insert_rowid())
}

/// Raw update with the same constraints as `create_model_alias_unchecked`.
#[cfg(test)]
fn update_model_alias_unchecked(
    pool: &DbPool,
    id: i64,
    alias: &str,
    target_model: &str,
    is_active: bool,
    fallback_targets: Option<&str>,
    strategy: Option<&str>,
) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "UPDATE model_aliases SET alias = ?2, target_model = ?3, is_active = ?4, fallback_targets = ?5, strategy = ?6 WHERE id = ?1",
        rusqlite::params![id, alias, target_model, is_active, fallback_targets, strategy.unwrap_or("first_available")],
    )?;
    Ok(())
}

/// Returns names that should be checked for alias-chain conflicts when
/// inserting / updating an alias row: the target model + every parsed
/// fallback. `fallback_targets` must be JSON (CLAUDE.md §9); a malformed
/// value is rejected loudly so a stale writer cannot bypass the chain
/// guard by smuggling in a non-parseable string.
fn collect_chain_candidates(
    target_model: &str,
    fallback_targets: Option<&str>,
) -> Result<Vec<String>> {
    let mut out = vec![target_model.trim().to_string()];
    if let Some(raw) = fallback_targets {
        let trimmed = raw.trim();
        if !trimmed.is_empty() {
            let parsed: Vec<String> = serde_json::from_str(trimmed)
                .map_err(|e| anyhow::anyhow!("fallback_targets must be JSON array: {}", e))?;
            out.extend(
                parsed
                    .into_iter()
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty()),
            );
        }
    }
    Ok(out)
}

/// SQLite-side helper used by every chain-aware path below. Returns true
/// when `name` matches an *active* alias other than `exclude_id` (so an
/// update does not flag itself when name is unchanged).
fn alias_is_active_within_tx(
    tx: &rusqlite::Connection,
    name: &str,
    exclude_id: Option<i64>,
) -> Result<bool> {
    let exists: Option<bool> = match exclude_id {
        Some(id) => tx
            .query_row(
                "SELECT 1 FROM model_aliases WHERE alias = ?1 AND is_active = 1 AND id != ?2",
                rusqlite::params![name, id],
                |_| Ok(true),
            )
            .optional()?,
        None => tx
            .query_row(
                "SELECT 1 FROM model_aliases WHERE alias = ?1 AND is_active = 1",
                rusqlite::params![name],
                |_| Ok(true),
            )
            .optional()?,
    };
    Ok(exists.unwrap_or(false))
}

/// Inverse direction of the chain check: scans every other active alias
/// and asks whether `name` already appears as their `target_model` or
/// inside their `fallback_targets`. Catches the case where someone
/// registers `child → real-model` first and then makes `real-model`
/// itself an active alias — without this scan the second insert passes
/// the outbound check (its target/fallbacks are real models) but the
/// runtime sees an active two-step chain.
fn alias_is_inbound_target_within_tx(
    tx: &rusqlite::Connection,
    name: &str,
    exclude_id: Option<i64>,
) -> Result<bool> {
    let mut stmt = tx.prepare(
        "SELECT id, target_model, fallback_targets FROM model_aliases WHERE is_active = 1",
    )?;
    let rows = stmt.query_map([], |row| {
        Ok((
            row.get::<_, i64>(0)?,
            row.get::<_, String>(1)?,
            row.get::<_, Option<String>>(2)?,
        ))
    })?;
    for row in rows {
        let (id, target, fallbacks) = row?;
        if Some(id) == exclude_id {
            continue;
        }
        if target.trim() == name {
            return Ok(true);
        }
        if let Some(raw) = fallbacks {
            // `collect_chain_candidates` requires a target argument; we only
            // care about the parsed fallback list here so call serde directly.
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                continue;
            }
            if let Ok(parsed) = serde_json::from_str::<Vec<String>>(trimmed) {
                if parsed.iter().any(|s| s.trim() == name) {
                    return Ok(true);
                }
            }
        }
    }
    Ok(false)
}

/// Atomic create — chain check + insert under a single transaction so two
/// concurrent admin writes cannot pass the validation independently and
/// then jointly create an alias chain.
pub fn create_model_alias_with_chain_check(
    pool: &DbPool,
    alias: &str,
    target_model: &str,
    fallback_targets: Option<&str>,
    strategy: Option<&str>,
) -> Result<i64> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let id = create_model_alias_with_chain_check_tx(
        &tx,
        alias,
        target_model,
        fallback_targets,
        strategy,
    )?;
    tx.commit()?;
    Ok(id)
}

/// Tx-level body of [`create_model_alias_with_chain_check`] — shared with
/// writers that must mutate an alias atomically WITH another row (vision
/// model publish registers the model and its alias in one transaction).
pub(crate) fn create_model_alias_with_chain_check_tx(
    tx: &rusqlite::Transaction<'_>,
    alias: &str,
    target_model: &str,
    fallback_targets: Option<&str>,
    strategy: Option<&str>,
) -> Result<i64> {
    let candidates = collect_chain_candidates(target_model, fallback_targets)?;
    for name in &candidates {
        if name.is_empty() {
            continue;
        }
        if alias_is_active_within_tx(tx, name, None)? {
            anyhow::bail!(
                "'{}' is itself an active alias; aliases of aliases are not supported",
                name
            );
        }
    }
    if alias_is_inbound_target_within_tx(tx, alias, None)? {
        anyhow::bail!(
            "alias '{}' is already used as a target/fallback by another active alias; \
             registering it would create a chain",
            alias
        );
    }
    // Blank target = unbound alias: store it parked so the router skips it until
    // an admin binds a model. A bound target inserts active.
    let active = !target_model.trim().is_empty();
    tx.execute(
        "INSERT INTO model_aliases (alias, target_model, is_active, fallback_targets, strategy) VALUES (?1, ?2, ?3, ?4, ?5)",
        rusqlite::params![alias, target_model, active, fallback_targets, strategy.unwrap_or("first_available")],
    )?;
    Ok(tx.last_insert_rowid())
}

/// Atomic update — same rationale as the create variant.
pub fn update_model_alias_with_chain_check(
    pool: &DbPool,
    id: i64,
    alias: &str,
    target_model: &str,
    is_active: bool,
    fallback_targets: Option<&str>,
    strategy: Option<&str>,
) -> Result<()> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    update_model_alias_with_chain_check_tx(
        &tx,
        id,
        alias,
        target_model,
        is_active,
        fallback_targets,
        strategy,
    )?;
    tx.commit()?;
    Ok(())
}

/// Tx-level body of [`update_model_alias_with_chain_check`] — see the create
/// variant for why writers may need to compose this into a larger transaction.
pub(crate) fn update_model_alias_with_chain_check_tx(
    tx: &rusqlite::Transaction<'_>,
    id: i64,
    alias: &str,
    target_model: &str,
    is_active: bool,
    fallback_targets: Option<&str>,
    strategy: Option<&str>,
) -> Result<()> {
    // Inactive rows cannot route, so they cannot create a chain. Skip the
    // check to keep operator workflows around "park then archive" simple.
    let candidates = if is_active {
        collect_chain_candidates(target_model, fallback_targets)?
    } else {
        Vec::new()
    };
    for name in &candidates {
        if name.is_empty() {
            continue;
        }
        if alias_is_active_within_tx(tx, name, Some(id))? {
            anyhow::bail!(
                "'{}' is itself an active alias; aliases of aliases are not supported",
                name
            );
        }
    }
    if is_active && alias_is_inbound_target_within_tx(tx, alias, Some(id))? {
        anyhow::bail!(
            "alias '{}' is already used as a target/fallback by another active alias; \
             activating this row would create a chain",
            alias
        );
    }
    tx.execute(
        "UPDATE model_aliases SET alias = ?2, target_model = ?3, is_active = ?4, fallback_targets = ?5, strategy = ?6 WHERE id = ?1",
        rusqlite::params![id, alias, target_model, is_active, fallback_targets, strategy.unwrap_or("first_available")],
    )?;
    Ok(())
}

pub fn delete_model_alias(pool: &DbPool, id: i64) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "DELETE FROM model_aliases WHERE id = ?1",
        rusqlite::params![id],
    )?;
    Ok(())
}

/// Zapisuje pelny snapshot aliasow otrzymany przez mesh sync
/// (`MESH_MSG_ALIAS_SYNC`). Upsert po nazwie aliasu zachowuje lokalne `id`
/// (tabele FK: owners/visibility/consumers wisza na `alias_id`), a wpisy
/// nieobecne w snapshocie sa usuwane. Walidacja chain-check jest pomijana —
/// nadawca zwalidowal mutacje przed broadcastem.
pub fn replace_model_aliases_from_sync(pool: &DbPool, aliases: &[DbModelAlias]) -> Result<()> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    for a in aliases {
        tx.execute(
            "INSERT INTO model_aliases (alias, target_model, is_active, fallback_targets, strategy) \
             VALUES (?1, ?2, ?3, ?4, ?5) \
             ON CONFLICT(alias) DO UPDATE SET \
                target_model = excluded.target_model, \
                is_active = excluded.is_active, \
                fallback_targets = excluded.fallback_targets, \
                strategy = excluded.strategy",
            rusqlite::params![
                a.alias,
                a.target_model,
                a.is_active,
                a.fallback_targets,
                a.strategy
            ],
        )?;
    }
    // Usun lokalne aliasy spoza snapshotu — snapshot jest pelnym stanem nadawcy.
    let names: Vec<&str> = aliases.iter().map(|a| a.alias.as_str()).collect();
    if names.is_empty() {
        tx.execute("DELETE FROM model_aliases", [])?;
    } else {
        let placeholders = (1..=names.len())
            .map(|i| format!("?{}", i))
            .collect::<Vec<_>>()
            .join(", ");
        tx.execute(
            &format!(
                "DELETE FROM model_aliases WHERE alias NOT IN ({})",
                placeholders
            ),
            rusqlite::params_from_iter(names.iter()),
        )?;
    }
    tx.commit()?;
    Ok(())
}

/// Validates alias identifier: `^[a-z][a-z0-9-]{0,63}$`.
/// Untrusted input (manifest may declare arbitrary alias id); reject early
/// so the registry cannot grow names that break URL routing or SQL LIKE
/// patterns elsewhere.
pub fn validate_alias_id(alias: &str) -> Result<()> {
    let bytes = alias.as_bytes();
    if bytes.is_empty() || bytes.len() > 64 {
        anyhow::bail!(
            "invalid alias id '{}': must be 1..=64 chars, got {}",
            alias.escape_debug(),
            bytes.len()
        );
    }
    if !(bytes[0].is_ascii_lowercase()) {
        anyhow::bail!(
            "invalid alias id '{}': must start with lowercase letter",
            alias.escape_debug()
        );
    }
    for &b in &bytes[1..] {
        if !(b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-') {
            anyhow::bail!(
                "invalid alias id '{}': only [a-z0-9-] allowed after first char",
                alias.escape_debug()
            );
        }
    }
    Ok(())
}

/// Creates the alias if it does not exist, or reactivates an existing one
/// without overwriting its `target_model`. Used by addon install/start to
/// register aliases declared in the addon manifest, and by admin UI for
/// manually managed aliases.
///
/// Ownership is recorded in `model_alias_owners` inside the same
/// transaction. `owner_type` must be `"addon"` or `"manual"`:
/// - `addon` requires `owner_id` = addon id; reusing the same alias from
///   another addon returns an error (cross-addon ownership conflict).
/// - `manual` ignores `owner_id` (NULL is stored).
///
/// Reactivation re-runs the chain check — a parked row may target a name
/// that became an alias in the meantime; flipping `is_active = 1` without
/// the check would create a forbidden alias-of-alias chain.
///
/// Returns the alias row id.
pub fn create_or_reactivate_model_alias(
    pool: &DbPool,
    alias: &str,
    default_target_model: &str,
    strategy: &str,
    owner_type: &str,
    owner_id: Option<&str>,
) -> Result<i64> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let alias_id = create_or_reactivate_model_alias_within_tx(
        &tx,
        alias,
        default_target_model,
        strategy,
        owner_type,
        owner_id,
    )?;
    tx.commit()?;
    Ok(alias_id)
}

/// Same as `create_or_reactivate_model_alias` but commits the alias in the
/// requested `is_active` state inside a single transaction. Used by the
/// addon install path for gated aliases: the router must never observe an
/// in-between window where a `gate=...` alias is active. Both the create
/// and the deactivate audit rows are written in one tx — on failure the
/// alias does not appear at all.
pub fn create_or_reactivate_model_alias_with_active(
    pool: &DbPool,
    alias: &str,
    default_target_model: &str,
    strategy: &str,
    owner_type: &str,
    owner_id: Option<&str>,
    is_active: bool,
) -> Result<i64> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    let alias_id = create_or_reactivate_model_alias_within_tx(
        &tx,
        alias,
        default_target_model,
        strategy,
        owner_type,
        owner_id,
    )?;
    if !is_active {
        // Caller wants the alias parked (gated). Reuse the audited setter so
        // the deactivate event is recorded with proper attribution.
        let changed_by = if owner_type == "addon" {
            owner_id
        } else {
            None
        };
        set_model_alias_active_audited_within_tx(&tx, alias, false, changed_by)?;
    }
    tx.commit()?;
    Ok(alias_id)
}

/// Same logic as `create_or_reactivate_model_alias`, but the caller owns
/// the transaction. Used by batch installers (addon manifest registration)
/// that need every alias write — including the audit row — to roll back
/// together on partial failure. `model_alias_changes` has no foreign key
/// to `model_aliases` (audit trail is preserved across deletes), so the
/// only reliable rollback is "tx never commits".
pub fn create_or_reactivate_model_alias_within_tx(
    tx: &rusqlite::Transaction<'_>,
    alias: &str,
    default_target_model: &str,
    strategy: &str,
    owner_type: &str,
    owner_id: Option<&str>,
) -> Result<i64> {
    validate_alias_id(alias)?;
    if owner_type != "addon" && owner_type != "manual" {
        anyhow::bail!(
            "invalid owner_type '{}': must be 'addon' or 'manual'",
            owner_type
        );
    }
    if owner_type == "addon" && owner_id.is_none() {
        anyhow::bail!("owner_type='addon' requires owner_id (addon id)");
    }
    let existing: Option<(i64, String, Option<String>)> = tx
        .query_row(
            "SELECT id, target_model, fallback_targets FROM model_aliases WHERE alias = ?1",
            rusqlite::params![alias],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()?;

    let (target_for_check, fallbacks_for_check, action_id): (String, Option<String>, Option<i64>) =
        match &existing {
            Some((id, target, fallbacks)) => (target.clone(), fallbacks.clone(), Some(*id)),
            None => (default_target_model.to_string(), None, None),
        };
    for name in collect_chain_candidates(&target_for_check, fallbacks_for_check.as_deref())? {
        if name.is_empty() {
            continue;
        }
        if alias_is_active_within_tx(tx, &name, action_id)? {
            anyhow::bail!(
                "'{}' is itself an active alias; aliases of aliases are not supported",
                name
            );
        }
    }
    if alias_is_inbound_target_within_tx(tx, alias, action_id)? {
        anyhow::bail!(
            "alias '{}' is already used as a target/fallback by another active alias; \
             registering or reactivating it would create a chain",
            alias
        );
    }

    // Ownership guard — block silent take-over across owner_type boundaries.
    // Cross-addon (addon→addon with different addon id) and manual↔addon
    // transitions all require explicit admin action (M16 reassign), never
    // a side effect of an install/reinstall.
    if let Some(id) = action_id {
        let existing_owner: Option<(String, Option<String>)> = tx
            .query_row(
                "SELECT owner_type, owner_id FROM model_alias_owners WHERE alias_id = ?1",
                rusqlite::params![id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        if let Some((ex_type, ex_owner_id)) = existing_owner {
            if ex_type == "addon" && owner_type == "addon" && ex_owner_id.as_deref() != owner_id {
                anyhow::bail!(
                    "alias '{}' is already owned by addon '{}'; cannot reassign to '{}'",
                    alias.escape_debug(),
                    ex_owner_id.unwrap_or_default(),
                    owner_id.unwrap_or_default()
                );
            }
            if ex_type == "manual" && owner_type == "addon" {
                anyhow::bail!(
                    "alias '{}' is manually owned; addon '{}' cannot adopt it silently (use admin M16 to reassign)",
                    alias.escape_debug(),
                    owner_id.unwrap_or("?")
                );
            }
            if ex_type == "addon" && owner_type == "manual" {
                anyhow::bail!(
                    "alias '{}' is owned by addon '{}'; manual ownership change requires admin M16",
                    alias.escape_debug(),
                    ex_owner_id.as_deref().unwrap_or("?")
                );
            }
        }
    }

    // Unbound aliases (blank effective target) stay parked: a manifest with an
    // empty `suggested_default` registers the alias but leaves the admin to bind
    // a model before the router will resolve it. `target_for_check` is the stored
    // target on reactivation and the manifest default on first create, so an
    // admin who cleared the binding keeps the alias parked across reinstalls.
    let active = !target_for_check.trim().is_empty();
    let alias_id: i64;
    let change_type: &str;
    if let Some(id) = action_id {
        tx.execute(
            "UPDATE model_aliases SET is_active = ?2 WHERE id = ?1",
            rusqlite::params![id, active],
        )?;
        alias_id = id;
        change_type = "activate";
    } else {
        tx.execute(
            "INSERT INTO model_aliases (alias, target_model, is_active, strategy) VALUES (?1, ?2, ?3, ?4)",
            rusqlite::params![alias, default_target_model, active, strategy],
        )?;
        alias_id = tx.last_insert_rowid();
        change_type = "create";
    }

    // Owner row: INSERT new (created_at = now) or UPDATE existing in place,
    // preserving the original `created_at` across reactivation. Cross-owner
    // transitions are blocked above, so the update only changes within the
    // same owner identity (idempotent reinstall).
    let stored_owner_id: Option<&str> = if owner_type == "addon" {
        owner_id
    } else {
        None
    };
    tx.execute(
        "INSERT INTO model_alias_owners (alias_id, owner_type, owner_id, created_at) \
         VALUES (?1, ?2, ?3, datetime('now')) \
         ON CONFLICT(alias_id) DO UPDATE SET \
             owner_type = excluded.owner_type, \
             owner_id = excluded.owner_id",
        rusqlite::params![alias_id, owner_type, stored_owner_id],
    )?;

    // Audit trail: one row per create/activate event.
    let after_snapshot = serde_json::json!({
        "alias": alias,
        "target_model": default_target_model,
        "is_active": active,
        "owner_type": owner_type,
        "owner_id": stored_owner_id,
    })
    .to_string();
    let changed_by_addon = if owner_type == "addon" {
        owner_id
    } else {
        None
    };
    tx.execute(
        "INSERT INTO model_alias_changes \
         (alias_id, alias_name, changed_by_addon_id, before_snapshot, after_snapshot, change_type, ts) \
         VALUES (?1, ?2, ?3, NULL, ?4, ?5, strftime('%s','now'))",
        rusqlite::params![alias_id, alias, changed_by_addon, after_snapshot, change_type],
    )?;

    Ok(alias_id)
}

/// Persists the capability `methods` of an alias as a JSON array string. Called
/// at install time from the owner addon's `[[alias]].methods` declaration so
/// consumers can later discover which capability (detect/recognize/embed/...)
/// each granted alias serves. An empty slice writes `[]`. Idempotent.
pub fn set_alias_methods_within_tx(
    tx: &rusqlite::Transaction<'_>,
    alias_id: i64,
    methods: &[String],
) -> Result<()> {
    let json = serde_json::to_string(methods)?;
    tx.execute(
        "UPDATE model_aliases SET methods = ?1 WHERE id = ?2",
        rusqlite::params![json, alias_id],
    )?;
    Ok(())
}

/// Sets the `is_active` flag on an alias selected by name.
///
/// Reactivation (`is_active = true`) re-runs the same chain check as
/// create/update — the row's target may have become an alias itself while
/// the flag was off, so a naive flag flip could resurrect a chain.
/// Deactivation is always safe; an inactive row does not route.
pub fn set_model_alias_active(pool: &DbPool, alias: &str, is_active: bool) -> Result<()> {
    set_model_alias_active_audited(pool, alias, is_active, None)
}

/// Same as `set_model_alias_active` but records `changed_by_addon_id` on
/// the audit row. Used by the generic addon install/start/stop path so
/// the audit trail attributes activate/deactivate events to the addon.
pub fn set_model_alias_active_audited(
    pool: &DbPool,
    alias: &str,
    is_active: bool,
    changed_by_addon_id: Option<&str>,
) -> Result<()> {
    let conn = acquire(pool)?;
    let tx = conn.unchecked_transaction()?;
    set_model_alias_active_audited_within_tx(&tx, alias, is_active, changed_by_addon_id)?;
    tx.commit()?;
    Ok(())
}

/// Same as `set_model_alias_active_audited`, but the caller owns the
/// transaction. Used by the addon install path to keep the gated-alias
/// deactivate inside the same tx as the create/reactivate above.
pub fn set_model_alias_active_audited_within_tx(
    tx: &rusqlite::Connection,
    alias: &str,
    is_active: bool,
    changed_by_addon_id: Option<&str>,
) -> Result<()> {
    let existing: Option<(i64, String, Option<String>, bool)> = tx
        .query_row(
            "SELECT id, target_model, fallback_targets, is_active FROM model_aliases WHERE alias = ?1",
            rusqlite::params![alias],
            |row| {
                let active: i64 = row.get(3)?;
                Ok((row.get(0)?, row.get(1)?, row.get(2)?, active != 0))
            },
        )
        .optional()?;
    if is_active {
        if let Some((id, target, fallbacks, _)) = &existing {
            for name in collect_chain_candidates(target, fallbacks.as_deref())? {
                if name.is_empty() {
                    continue;
                }
                if alias_is_active_within_tx(tx, &name, Some(*id))? {
                    anyhow::bail!(
                        "'{}' is itself an active alias; aliases of aliases are not supported",
                        name
                    );
                }
            }
            if alias_is_inbound_target_within_tx(tx, alias, Some(*id))? {
                anyhow::bail!(
                    "alias '{}' is already used as a target/fallback by another active alias; \
                     activating this row would create a chain",
                    alias
                );
            }
        }
    }
    tx.execute(
        "UPDATE model_aliases SET is_active = ?1 WHERE alias = ?2",
        rusqlite::params![is_active, alias],
    )?;

    // Audit only when the row actually exists and the flag transitions —
    // double-deactivate stays idempotent without churn in the changes log.
    if let Some((id, target, _, prev_active)) = existing {
        if prev_active != is_active {
            let before = serde_json::json!({ "is_active": prev_active }).to_string();
            let after = serde_json::json!({
                "alias": alias,
                "target_model": target,
                "is_active": is_active,
            })
            .to_string();
            let change_type = if is_active { "activate" } else { "deactivate" };
            tx.execute(
                "INSERT INTO model_alias_changes \
                 (alias_id, alias_name, changed_by_addon_id, before_snapshot, after_snapshot, change_type, ts) \
                 VALUES (?1, ?2, ?3, ?4, ?5, ?6, strftime('%s','now'))",
                rusqlite::params![
                    id,
                    alias,
                    changed_by_addon_id,
                    before,
                    after,
                    change_type
                ],
            )?;
        }
    }
    Ok(())
}

