pub fn add_cluster_member(
    pool: &DbPool,
    cluster_id: &str,
    node_id: &str,
    role: &str,
    interface_name: &str,
    interface_ip: &str,
    interface_speed_mbps: i64,
    interface_type: &str,
) -> Result<()> {
    let conn = acquire(pool)?;
    // UPSERT, nie INSERT OR REPLACE: REPLACE kasuje wiersz i wstawia nowy, wiec
    // gubil kolumny spoza tej listy — konfiguracje RDMA (`rdma_*`) i `joined_at`.
    // Ponowne dodanie noda po cichu rozbrajalo klaster do deployu.
    //
    // NULLIF/COALESCE: puste pole znaczy "nie podano", nie "wyczysc". Dodanie
    // noda bez jawnego wyboru karty nie moze skasowac przypisania z testu
    // polaczen ani recznego wyboru admina.
    conn.execute(
        "INSERT INTO cluster_members (cluster_id, node_id, role, interface_name, interface_ip, interface_speed_mbps, interface_type) \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7) \
         ON CONFLICT(cluster_id, node_id) DO UPDATE SET \
           role = excluded.role, \
           interface_name = COALESCE(NULLIF(excluded.interface_name, ''), cluster_members.interface_name), \
           interface_ip = COALESCE(NULLIF(excluded.interface_ip, ''), cluster_members.interface_ip), \
           interface_speed_mbps = COALESCE(NULLIF(excluded.interface_speed_mbps, 0), cluster_members.interface_speed_mbps), \
           interface_type = COALESCE(NULLIF(excluded.interface_type, ''), cluster_members.interface_type)",
        rusqlite::params![cluster_id, node_id, role, interface_name, interface_ip, interface_speed_mbps, interface_type],
    )?;
    Ok(())
}

/// Aktualizuje TYLKO kolumny interfejsu wybranego czlonka (po tescie polaczen).
/// Nie rusza `role`/`joined_at` — w przeciwienstwie do `add_cluster_member`
/// (INSERT OR REPLACE), ktory zresetowalby date dolaczenia.
pub fn update_cluster_member_interface(
    pool: &DbPool,
    cluster_id: &str,
    node_id: &str,
    interface_name: &str,
    interface_ip: &str,
    interface_speed_mbps: i64,
    interface_type: &str,
) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "UPDATE cluster_members SET interface_name = ?3, interface_ip = ?4, interface_speed_mbps = ?5, interface_type = ?6 WHERE cluster_id = ?1 AND node_id = ?2",
        rusqlite::params![cluster_id, node_id, interface_name, interface_ip, interface_speed_mbps, interface_type],
    )?;
    Ok(())
}

/// Znajduje cluster, ktorego zbior `node_id` czlonkow jest rowny podanemu
/// zbiorowi. Uzywane przez probe stream, gdy request nie niesie `cluster_id`.
pub fn find_cluster_by_member_set(pool: &DbPool, node_ids: &[String]) -> Result<Option<String>> {
    let target: std::collections::HashSet<&str> = node_ids.iter().map(|s| s.as_str()).collect();
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached("SELECT cluster_id FROM clusters")?;
    let cluster_ids: Vec<String> = stmt
        .query_map([], |row| row.get::<_, String>(0))?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    drop(stmt);
    for cluster_id in cluster_ids {
        let mut mstmt =
            conn.prepare_cached("SELECT node_id FROM cluster_members WHERE cluster_id = ?1")?;
        let members: std::collections::HashSet<String> = mstmt
            .query_map(rusqlite::params![cluster_id], |row| row.get::<_, String>(0))?
            .collect::<std::result::Result<std::collections::HashSet<_>, _>>()?;
        if members.len() == target.len() && members.iter().all(|m| target.contains(m.as_str())) {
            return Ok(Some(cluster_id));
        }
    }
    Ok(None)
}

pub fn remove_cluster_member(pool: &DbPool, cluster_id: &str, node_id: &str) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "DELETE FROM cluster_members WHERE cluster_id = ?1 AND node_id = ?2",
        rusqlite::params![cluster_id, node_id],
    )?;
    Ok(())
}

/// Lista klastrow z agregatem liczby czlonkow. Liczba online nie jest w DB —
/// wylicza ja handler z peer_store.
pub fn list_clusters_with_counts(
    pool: &DbPool,
) -> Result<Vec<crate::db::models::DbClusterWithCounts>> {
    let conn = acquire(pool)?;
    let sql = format!(
        "SELECT {}, \
         (SELECT COUNT(*) FROM cluster_members cm WHERE cm.cluster_id = c.cluster_id) AS members_count \
         FROM clusters c ORDER BY name",
        CLUSTER_COLS.split(',').map(|s| format!("c.{}", s.trim())).collect::<Vec<_>>().join(", ")
    );
    let mut stmt = conn.prepare_cached(&sql)?;
    let rows = stmt
        .query_map([], |row| {
            let cluster = row_to_cluster(row)?;
            let members_count: i64 = row.get(16)?;
            Ok(crate::db::models::DbClusterWithCounts {
                cluster,
                members_count,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

/// Pelna aktualizacja klastra wraz z polami failover + health-check + timeout.
/// Pola `Option::None` zachowuja dotychczasowa wartosc (COALESCE).
pub fn update_cluster_full(
    pool: &DbPool,
    cluster_id: &str,
    name: Option<&str>,
    description: Option<&str>,
    strategy: Option<&str>,
    failover_enabled: Option<bool>,
    failover_target: Option<Option<&str>>,
    health_check_interval_ms: Option<i64>,
    timeout_ms: Option<i64>,
) -> Result<()> {
    let conn = acquire(pool)?;
    let failover_target_param: Option<&str> = failover_target.unwrap_or(None);
    let failover_target_provided = failover_target.is_some();
    conn.execute(
        "UPDATE clusters SET \
            name = COALESCE(?2, name), \
            description = COALESCE(?3, description), \
            strategy = COALESCE(?4, strategy), \
            failover_enabled = COALESCE(?5, failover_enabled), \
            failover_target = CASE WHEN ?6 = 1 THEN ?7 ELSE failover_target END, \
            health_check_interval_ms = COALESCE(?8, health_check_interval_ms), \
            timeout_ms = COALESCE(?9, timeout_ms), \
            updated_at = datetime('now') \
         WHERE cluster_id = ?1",
        rusqlite::params![
            cluster_id,
            name,
            description,
            strategy,
            failover_enabled.map(|b| if b { 1i64 } else { 0i64 }),
            if failover_target_provided { 1i64 } else { 0i64 },
            failover_target_param,
            health_check_interval_ms,
            timeout_ms,
        ],
    )?;
    Ok(())
}

pub fn list_cluster_members(pool: &DbPool, cluster_id: &str) -> Result<Vec<DbClusterMember>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(&format!(
        "SELECT {} FROM cluster_members WHERE cluster_id = ?1 ORDER BY joined_at",
        CLUSTER_MEMBER_COLS
    ))?;
    let rows = stmt
        .query_map(rusqlite::params![cluster_id], row_to_cluster_member)?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

