fn flow_changed_fields(
    params: &FlowParams<'_>,
) -> BTreeMap<String, crate::sync::ledger::FieldValue> {
    let mut fields = BTreeMap::new();
    fields.insert("name".to_string(), field_string(params.name));
    fields.insert(
        "description".to_string(),
        field_optional_string(params.description),
    );
    fields.insert(
        "is_default".to_string(),
        crate::sync::ledger::FieldValue::Bool(params.is_default),
    );
    fields.insert(
        "service_type".to_string(),
        field_optional_string(params.service_type),
    );
    fields.insert("flow_json".to_string(), field_string(params.flow_json));
    fields.insert("status".to_string(), field_string(params.status));
    fields.insert(
        "published_model_name".to_string(),
        field_optional_string(params.published_model_name),
    );
    // FlowParams deliberately has no is_system and user handlers reject edits
    // of system flows, so every capture minted here is explicitly non-system.
    // The column still travels: apply_flow's seed-guard uses it to distinguish
    // a user edit (is_system=false → rejected on a local system row) from a
    // seed refresh (is_system=true → accepted).
    fields.insert(
        "is_system".to_string(),
        crate::sync::ledger::FieldValue::Bool(false),
    );
    fields
}

