pub fn create_flow(pool: &DbPool, params: &FlowParams<'_>) -> Result<String> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    let id = uuid::Uuid::new_v4().to_string();
    tx.execute(
        "INSERT INTO flows (id, name, description, is_default, service_type, flow_json, status, published_model_name) \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
        rusqlite::params![
            id,
            params.name,
            params.description,
            params.is_default,
            params.service_type,
            params.flow_json,
            params.status,
            params.published_model_name,
        ],
    )?;
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::Flow,
        id.clone(),
        crate::sync::runtime::SqlWriteAction::Insert,
        flow_changed_fields(params),
        params.actor_user_id.map(|id| id.to_string()),
    )?;
    tx.commit()?;
    Ok(id)
}

pub fn update_flow(
    pool: &DbPool,
    id: &str,
    expected_version: i64,
    params: &FlowParams<'_>,
) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    let rows_affected = tx.execute(
        "UPDATE flows \
         SET name = ?2, description = ?3, is_default = ?4, service_type = ?5, \
             flow_json = ?6, status = ?7, published_model_name = ?8, \
             version = version + 1, updated_at = datetime('now') \
         WHERE id = ?1 AND version = ?9",
        rusqlite::params![
            id,
            params.name,
            params.description,
            params.is_default,
            params.service_type,
            params.flow_json,
            params.status,
            params.published_model_name,
            expected_version,
        ],
    )?;
    if rows_affected == 0 {
        return Err(anyhow::anyhow!("CONFLICT"));
    }
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::Flow,
        id.to_string(),
        crate::sync::runtime::SqlWriteAction::Update,
        flow_changed_fields(params),
        params.actor_user_id.map(|id| id.to_string()),
    )?;
    tx.commit()?;
    Ok(())
}

pub fn delete_flow(pool: &DbPool, id: &str) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    let rows_affected = tx.execute("DELETE FROM flows WHERE id = ?1", rusqlite::params![id])?;
    if rows_affected > 0 {
        let mut fields = BTreeMap::new();
        fields.insert("id".to_string(), field_string(id));
        record_core_capture_tx(
            &tx,
            crate::sync::core_registry::CoreSyncResourceKind::Flow,
            id.to_string(),
            crate::sync::runtime::SqlWriteAction::Delete,
            fields,
            None,
        )?;
    }
    tx.commit()?;
    Ok(())
}

// --- Flow Versions ---

/// Maksymalna liczba wersji historii przechowywana per flow.
pub const FLOW_VERSIONS_KEEP: i64 = 5;

const FLOW_VERSION_LIST_COLS: &str =
    "id, flow_id, version_num, name, description, status, created_at, created_by";
const FLOW_VERSION_FULL_COLS: &str =
    "id, flow_id, version_num, name, description, status, created_at, created_by, flow_json";

fn row_to_flow_version_list(row: &rusqlite::Row<'_>) -> rusqlite::Result<DbFlowVersion> {
    Ok(DbFlowVersion {
        id: row.get(0)?,
        flow_id: row.get(1)?,
        version_num: row.get(2)?,
        name: row.get(3)?,
        description: row.get(4)?,
        status: row.get(5)?,
        created_at: row.get(6)?,
        created_by: row.get(7)?,
        flow_json: None,
    })
}

fn row_to_flow_version_full(row: &rusqlite::Row<'_>) -> rusqlite::Result<DbFlowVersion> {
    Ok(DbFlowVersion {
        id: row.get(0)?,
        flow_id: row.get(1)?,
        version_num: row.get(2)?,
        name: row.get(3)?,
        description: row.get(4)?,
        status: row.get(5)?,
        created_at: row.get(6)?,
        created_by: row.get(7)?,
        flow_json: Some(row.get(8)?),
    })
}

/// Zwraca liste wersji (bez flow_json) posortowana malejaco, max 5.
pub fn list_flow_versions(pool: &DbPool, flow_id: &str) -> Result<Vec<DbFlowVersion>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(&format!(
        "SELECT {} FROM flow_versions WHERE flow_id = ?1 \
         ORDER BY version_num DESC LIMIT {}",
        FLOW_VERSION_LIST_COLS, FLOW_VERSIONS_KEEP
    ))?;
    let rows = stmt
        .query_map(rusqlite::params![flow_id], row_to_flow_version_list)?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

/// Zwraca pojedyncza wersje z pelnym flow_json.
pub fn get_flow_version(
    pool: &DbPool,
    flow_id: &str,
    version_id: &str,
) -> Result<Option<DbFlowVersion>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(&format!(
        "SELECT {} FROM flow_versions WHERE flow_id = ?1 AND id = ?2",
        FLOW_VERSION_FULL_COLS
    ))?;
    let result = stmt
        .query_row(
            rusqlite::params![flow_id, version_id],
            row_to_flow_version_full,
        )
        .optional()?;
    Ok(result)
}

/// Atomowa aktualizacja flow z zachowaniem snapshotu poprzedniej wersji.
///
/// W jednej transakcji: (1) zapisuje obecny stan do flow_versions z kolejnym
/// version_num, (2) prunuje wersje starsze niz FLOW_VERSIONS_KEEP, (3)
/// wykonuje UPDATE z optimistic locking.
///
/// Zwraca `Err("CONFLICT")` jesli expected_version nie pasuje.
pub fn update_flow_with_snapshot(
    pool: &DbPool,
    id: &str,
    expected_version: i64,
    params: &FlowParams<'_>,
    created_by: Option<&str>,
) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;

    // Pobierz aktualny stan do snapshotu (jesli flow istnieje)
    let current: Option<(String, Option<String>, Option<String>, String)> = tx
        .query_row(
            "SELECT name, description, status, flow_json FROM flows WHERE id = ?1",
            rusqlite::params![id],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)),
        )
        .optional()?;

    if let Some((old_name, old_description, old_status, old_flow_json)) = current {
        // Kolejny numer wersji dla tego flow
        let next_ver: i64 = tx.query_row(
            "SELECT COALESCE(MAX(version_num), 0) + 1 FROM flow_versions WHERE flow_id = ?1",
            rusqlite::params![id],
            |r| r.get(0),
        )?;

        // flow_versions replicates as an append-only core sync resource. The org
        // is DEFAULT_ORG_ID at this write site, mirroring the sibling flow
        // capture (flows here are default-org scoped).
        let version_id = uuid::Uuid::new_v4().to_string();
        tx.execute(
            "INSERT INTO flow_versions \
             (id, flow_id, version_num, flow_json, name, description, status, created_by) \
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
            rusqlite::params![
                version_id,
                id,
                next_ver,
                old_flow_json,
                old_name,
                old_description,
                old_status,
                created_by,
            ],
        )?;
        record_core_capture_tx(
            &tx,
            crate::sync::core_registry::CoreSyncResourceKind::FlowVersion,
            version_id.clone(),
            crate::sync::runtime::SqlWriteAction::Insert,
            flow_version_changed_fields(
                id,
                next_ver,
                &old_name,
                old_description.as_deref(),
                old_status.as_deref().unwrap_or("draft"),
                created_by,
                &old_flow_json,
            ),
            None,
        )?;

        // Prune — zostawiamy tylko FLOW_VERSIONS_KEEP najnowszych. Pruned rows are
        // emitted as Delete captures so peers drop the same trimmed snapshots.
        let pruned: Vec<String> = {
            let mut stmt = tx.prepare(
                "SELECT id FROM flow_versions WHERE flow_id = ?1 AND id NOT IN ( \
                   SELECT id FROM flow_versions WHERE flow_id = ?1 \
                   ORDER BY version_num DESC LIMIT ?2 \
                 )",
            )?;
            let collected = stmt
                .query_map(rusqlite::params![id, FLOW_VERSIONS_KEEP], |r| {
                    r.get::<_, String>(0)
                })?
                .collect::<std::result::Result<Vec<_>, _>>()?;
            collected
        };
        for pruned_id in &pruned {
            tx.execute(
                "DELETE FROM flow_versions WHERE id = ?1",
                rusqlite::params![pruned_id],
            )?;
            let mut fields = BTreeMap::new();
            fields.insert("id".to_string(), field_string(pruned_id));
            record_core_capture_tx(
                &tx,
                crate::sync::core_registry::CoreSyncResourceKind::FlowVersion,
                pruned_id.clone(),
                crate::sync::runtime::SqlWriteAction::Delete,
                fields,
                None,
            )?;
        }
    }

    // Wlasciwa aktualizacja z optimistic locking
    let rows_affected = tx.execute(
        "UPDATE flows SET name = ?2, description = ?3, is_default = ?4, service_type = ?5, \
         flow_json = ?6, status = ?7, version = version + 1, updated_at = datetime('now') \
         WHERE id = ?1 AND version = ?8",
        rusqlite::params![
            id,
            params.name,
            params.description,
            params.is_default,
            params.service_type,
            params.flow_json,
            params.status,
            expected_version
        ],
    )?;
    if rows_affected == 0 {
        return Err(anyhow::anyhow!("CONFLICT"));
    }
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::Flow,
        id.to_string(),
        crate::sync::runtime::SqlWriteAction::Update,
        flow_changed_fields(params),
        params.actor_user_id.map(|id| id.to_string()),
    )?;

    tx.commit()?;
    Ok(())
}

// --- Flow Model Bindings ---

const FLOW_BINDING_COLS: &str = "id, flow_id, model_pattern, priority";

