/// Opens a run's audit row. The provenance stamp is written HERE, at insert:
/// the entry point already minted it, and a row that starts unattributed could
/// never be told apart from a pre-v135 one.
pub fn create_flow_execution(pool: &DbPool, exec: &NewFlowExecution<'_>) -> Result<i64> {
    let conn = acquire(pool)?;
    conn.execute(
        "INSERT INTO flow_executions \
         (flow_id, request_id, started_at, status, parent_execution_id, \
          origin, actor_kind, actor_id, actor_user_id, correlation_id) \
         VALUES (?1, ?2, datetime('now'), ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
        rusqlite::params![
            exec.flow_id,
            exec.request_id,
            exec.status,
            exec.parent_execution_id,
            exec.origin,
            exec.actor_kind,
            exec.actor_id,
            exec.actor_user_id,
            exec.correlation_id,
        ],
    )?;
    Ok(conn.last_insert_rowid())
}

/// Closes a run's audit row. `model` is the model the run's last LLM call
/// resolved to — only known now, not at insert — and is `None` for a flow that
/// called no model (spec invariant 6: a gap, not a guess). `result_metadata`
/// is the domain-specific JSON blob (migration v139, `flow_executions.result_metadata_json`)
/// the run produced — also only known at finalization, e.g. exam type or
/// patient pseudonym for CMC SILESIA — and `None` when the run's flow wrote
/// none.
pub fn update_flow_execution(
    pool: &DbPool,
    id: i64,
    status: &str,
    model: Option<&str>,
    execution_log: Option<&str>,
    total_latency_ms: Option<i64>,
    total_tokens: Option<i64>,
    result_metadata: Option<&str>,
) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "UPDATE flow_executions SET finished_at = datetime('now'), status = ?2, model = ?3, execution_log = ?4, total_latency_ms = ?5, total_tokens = ?6, result_metadata_json = ?7 WHERE id = ?1",
        rusqlite::params![
            id,
            status,
            model,
            execution_log,
            total_latency_ms,
            total_tokens,
            result_metadata
        ],
    )?;
    Ok(())
}

pub fn delete_flow_execution(pool: &DbPool, id: i64) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "DELETE FROM flow_executions WHERE id = ?1",
        rusqlite::params![id],
    )?;
    Ok(())
}

