const USER_ACCOUNT_COLS: &str =
    "id, username, password_hash, display_name, email, is_active, is_admin, must_change_password, \
     sso_provider, sso_subject, last_login_at, created_at, updated_at, role";

/// Ustaw role usera. Akceptuje tylko 'user' | 'power_user' | 'admin'.
/// is_admin jest synchronizowany automatycznie (role='admin' → is_admin=1).
pub fn set_user_role(pool: &DbPool, user_id: &str, role: &str) -> Result<()> {
    let role = match role {
        "user" | "power_user" | "admin" => role,
        _ => anyhow::bail!("Nieprawidlowa rola: {}", role),
    };
    let is_admin = role == "admin";
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    let rows_affected = tx.execute(
        "UPDATE user_accounts SET role = ?1, is_admin = ?2, updated_at = datetime('now') WHERE id = ?3",
        rusqlite::params![role, is_admin, user_id],
    )?;
    if rows_affected > 0 {
        let mut fields = BTreeMap::new();
        fields.insert("role".to_string(), field_string(role));
        fields.insert(
            "is_admin".to_string(),
            crate::sync::ledger::FieldValue::Bool(is_admin),
        );
        record_core_capture_tx(
            &tx,
            crate::sync::core_registry::CoreSyncResourceKind::UserAccount,
            user_id.to_string(),
            crate::sync::runtime::SqlWriteAction::Update,
            fields,
            None,
        )?;
        bump_sync_permission_epoch_with_conn(&tx, crate::services::org::DEFAULT_ORG_ID)?;
    }
    tx.commit()?;
    Ok(())
}

/// Zwraca `(role, is_admin)` uzytkownika z `user_accounts` lub `None` gdy nie istnieje.
/// Zrodlo prawdy o rolach userow to baza CORE — ML Studio nie trzyma wlasnej kopii rol.
pub fn get_user_role(pool: &DbPool, user_id: &str) -> Result<Option<(String, bool)>> {
    let conn = acquire(pool)?;
    let result = conn
        .query_row(
            "SELECT role, is_admin FROM user_accounts WHERE id = ?1",
            rusqlite::params![user_id],
            |row| {
                let role: String = row.get(0)?;
                let is_admin: bool = row.get(1)?;
                Ok((role, is_admin))
            },
        )
        .optional()?;
    Ok(result)
}

