/// Tworzy uzytkownika z logowaniem SSO (bez hasla).
pub fn create_user_account_sso(
    pool: &DbPool,
    username: &str,
    display_name: &str,
    email: &str,
    sso_provider: &str,
    sso_subject: &str,
) -> Result<String> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    let id = uuid::Uuid::new_v4().to_string();
    // Haslo = losowy hash (uzytkownik SSO nie loguje sie haslem)
    let random_hash = format!("$sso${}${}", sso_provider, uuid::Uuid::new_v4());
    tx.execute(
        "INSERT INTO user_accounts (id, username, password_hash, display_name, email, \
         sso_provider, sso_subject, is_active) \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 1)",
        rusqlite::params![
            id,
            username,
            random_hash,
            display_name,
            email,
            sso_provider,
            sso_subject
        ],
    )?;
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::UserAccount,
        id.clone(),
        crate::sync::runtime::SqlWriteAction::Insert,
        user_account_changed_fields(Some(username), Some(display_name), Some(email), Some(true)),
        None,
    )?;
    tx.commit()?;
    Ok(id)
}

/// Wyszukuje uzytkownika po SSO provider + subject.
pub fn get_user_account_by_sso(
    pool: &DbPool,
    sso_provider: &str,
    sso_subject: &str,
) -> Result<Option<UserAccount>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(&format!(
        "SELECT {} FROM user_accounts WHERE sso_provider = ?1 AND sso_subject = ?2",
        USER_ACCOUNT_COLS
    ))?;
    let result = stmt
        .query_row(
            rusqlite::params![sso_provider, sso_subject],
            row_to_user_account,
        )
        .optional()?;
    Ok(result)
}

/// Aktualizuje last_login_at uzytkownika.
