/// Pobiera wszystkie ustawienia konfiguracji addonu jako HashMap
pub fn get_addon_config_values(
    pool: &DbPool,
    addon_id: &str,
) -> Result<std::collections::HashMap<String, String>> {
    let conn = acquire(pool)?;
    let prefix = format!("addon_config:{}:", addon_id);
    let mut stmt = conn.prepare_cached("SELECT key, value FROM settings WHERE key LIKE ?1")?;
    let rows = stmt.query_map(rusqlite::params![format!("{}%", prefix)], |row| {
        let full_key: String = row.get(0)?;
        let value: String = row.get(1)?;
        let short_key = full_key
            .strip_prefix(&prefix)
            .unwrap_or(&full_key)
            .to_string();
        Ok((short_key, value))
    })?;
    let mut map = std::collections::HashMap::new();
    for row in rows {
        let (k, v) = row?;
        map.insert(k, v);
    }
    Ok(map)
}

// =============================================================================
// Trusted Nodes — zaufane nody mesh
// =============================================================================

/// Dodaje zaufany node do bazy
pub fn add_trusted_node(
    pool: &DbPool,
    node_id: &str,
    public_key_hex: &str,
    hostname: &str,
    approved_by: &str,
    approved_at: Option<&str>,
) -> Result<()> {
    let conn = acquire(pool)?;
    // `approved_at` is the trust-expiry TTL anchor. A real local pairing passes `None`
    // and we stamp `now`. A mirror re-add (TrustedKeysSync / first-contact propagation)
    // passes the ORIGIN's `approved_at`, so a long-dead identity keeps its old timestamp
    // and is pruned again next cycle instead of resurrecting with a fresh clock.
    match approved_at.map(str::trim).filter(|s| !s.is_empty()) {
        Some(at) => conn.execute(
            "INSERT OR REPLACE INTO trusted_nodes (node_id, public_key, hostname, approved_by, approved_at, is_active) \
             VALUES (?1, ?2, ?3, ?4, ?5, 1)",
            rusqlite::params![node_id, public_key_hex, hostname, approved_by, at],
        )?,
        None => conn.execute(
            "INSERT OR REPLACE INTO trusted_nodes (node_id, public_key, hostname, approved_by, approved_at, is_active) \
             VALUES (?1, ?2, ?3, ?4, datetime('now'), 1)",
            rusqlite::params![node_id, public_key_hex, hostname, approved_by],
        )?,
    };
    drop(conn);
    ensure_default_core_sync_policies(pool)?;
    ensure_trusted_nodes_in_sync_identity(pool)?;
    Ok(())
}

/// Pobiera liste zaufanych nodow
pub fn list_trusted_nodes(pool: &DbPool) -> Result<Vec<TrustedNode>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT id, node_id, public_key, hostname, approved_by, approved_at, is_active, last_addresses, environment \
         FROM trusted_nodes WHERE is_active = 1 ORDER BY approved_at DESC",
    )?;
    let rows = stmt
        .query_map([], |row| {
            Ok(TrustedNode {
                id: row.get(0)?,
                node_id: row.get(1)?,
                public_key: row.get(2)?,
                hostname: row.get(3)?,
                approved_by: row.get(4)?,
                approved_at: row.get(5)?,
                is_active: row.get(6)?,
                last_addresses: row.get(7)?,
                environment: row.get(8)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

/// Persists the environment (Dev/Test/Prod, ROADMAP Z12) a peer declared at
/// pairing handshake time. A no-op (not an error) when the peer is not yet
/// (or no longer) a trusted node — the handshake writes `trusted_nodes` via
/// `add_trusted_node` first, so the row exists by the time this is called on
/// the happy path; a stale/rejected handshake simply has nothing to stamp.
pub fn set_trusted_node_environment(
    pool: &DbPool,
    node_id: &str,
    environment: tentaflow_protocol::environment::NodeEnvironment,
) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "UPDATE trusted_nodes SET environment = ?2 WHERE node_id = ?1 AND is_active = 1",
        rusqlite::params![node_id, environment.as_str()],
    )?;
    Ok(())
}

/// Environment declared by `node_id` at pairing time. `None` ("unknown") when
/// the node is not a currently-active trusted node OR was trust-paired before
/// this column existed (a NULL row) — callers MUST treat `None` as
/// fail-closed (never a same-environment match), never silently default it to
/// `Prod`. The only place that still applies a `Prod` default for a missing
/// value is per-OPERATION admission (`SyncOperationBody::environment`'s
/// `#[serde(default)]`, ROADMAP Z12 P1-2) — that keeps an existing Prod-Prod
/// mesh syncing across the v25->v26 upgrade without a migration step. This
/// function is the trust-table lookup used by the outbox environment filter
/// (`sync::runtime::outbox_target_still_allowed`), the catalog builder
/// (`services::catalog::provider::build_service_model_entries`) and the
/// config-bundle donor list — all of which must fail closed on `None`.
pub fn get_trusted_node_environment(
    pool: &DbPool,
    node_id: &str,
) -> Result<Option<tentaflow_protocol::environment::NodeEnvironment>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT environment FROM trusted_nodes WHERE node_id = ?1 AND is_active = 1",
    )?;
    let raw: Option<String> = stmt
        .query_row(rusqlite::params![node_id], |row| row.get(0))
        .optional()?
        .flatten();
    Ok(raw.and_then(|s| tentaflow_protocol::environment::NodeEnvironment::parse(&s)))
}

/// Environment per active trusted node id — batch form of
/// `get_trusted_node_environment`, used when building the catalog snapshot
/// (one query instead of one per mesh service entry). A node absent from the
/// returned map (or mapped to `None`) is "unknown" and MUST be treated
/// fail-closed by callers, same as the single-node lookup above.
pub fn list_trusted_node_environments(
    pool: &DbPool,
) -> Result<
    std::collections::HashMap<String, Option<tentaflow_protocol::environment::NodeEnvironment>>,
> {
    let conn = acquire(pool)?;
    let mut stmt =
        conn.prepare_cached("SELECT node_id, environment FROM trusted_nodes WHERE is_active = 1")?;
    let rows = stmt.query_map([], |row| {
        let node_id: String = row.get(0)?;
        let raw: Option<String> = row.get(1)?;
        Ok((node_id, raw))
    })?;
    let mut map = std::collections::HashMap::new();
    for row in rows {
        let (node_id, raw) = row?;
        let environment =
            raw.and_then(|s| tentaflow_protocol::environment::NodeEnvironment::parse(&s));
        map.insert(node_id, environment);
    }
    Ok(map)
}

/// Aktualizuje ostatnie znane adresy trusted noda
pub fn update_trusted_node_addresses(pool: &DbPool, node_id: &str, addresses: &str) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "UPDATE trusted_nodes SET last_addresses = ?2 WHERE node_id = ?1 AND is_active = 1",
        rusqlite::params![node_id, addresses],
    )?;
    Ok(())
}

/// Usuwa zaufany node z bazy
pub fn remove_trusted_node(pool: &DbPool, node_id: &str) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "DELETE FROM trusted_nodes WHERE node_id = ?1",
        rusqlite::params![node_id],
    )?;
    Ok(())
}

/// Zwraca ostatni utrwalony czas udanego polaczenia (`peer_persisted.last_seen_ms`,
/// epoka UNIX w ms) dla peera identyfikowanego heksowym node_id. `None` gdy node_id
/// nie jest poprawnym 32-bajtowym kluczem albo nie ma jeszcze wiersza w `peer_persisted`
/// (np. peer sparowany, ale nigdy nie polaczony). Uzywane przez prune wygaslego
/// zaufania — to trwaly sygnal "ostatniego sukcesu", wiec przetrwa restart.
pub fn get_peer_last_seen_ms(pool: &DbPool, node_id_hex: &str) -> Result<Option<i64>> {
    let mut id_bytes = [0u8; 32];
    if hex::decode_to_slice(node_id_hex, &mut id_bytes).is_err() {
        return Ok(None);
    }
    let conn = acquire(pool)?;
    let result = conn
        .query_row(
            "SELECT last_seen_ms FROM peer_persisted WHERE node_id = ?1",
            rusqlite::params![id_bytes.as_slice()],
            |row| row.get::<_, i64>(0),
        )
        .optional()?;
    Ok(result)
}

/// Usuwa wiersz tozsamosci sync dla noda, zdejmujac go z zbioru celow synchronizacji
/// (`list_permission_filtered_sync_targets_*` filtruje po `trust_status='trusted'`).
/// Wolane przy prune wygaslego zaufania, zeby martwa tozsamosc nie zostawala celem
/// replikacji. Idempotentne — brak wiersza nie jest bledem.
pub fn delete_sync_node(pool: &DbPool, node_id: &str) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "DELETE FROM sync_nodes WHERE node_id = ?1",
        rusqlite::params![node_id],
    )?;
    Ok(())
}

/// Sprawdza czy node jest zaufany
pub fn is_node_trusted(pool: &DbPool, node_id: &str) -> Result<bool> {
    let conn = acquire(pool)?;
    let count: i64 = conn.query_row(
        "SELECT COUNT(*) FROM trusted_nodes WHERE node_id = ?1 AND is_active = 1",
        rusqlite::params![node_id],
        |row| row.get(0),
    )?;
    Ok(count > 0)
}

/// Pobiera klucz publiczny zaufanego noda
pub fn get_trusted_node_public_key(pool: &DbPool, node_id: &str) -> Result<Option<String>> {
    let conn = acquire(pool)?;
    let result = conn
        .query_row(
            "SELECT public_key FROM trusted_nodes WHERE node_id = ?1 AND is_active = 1",
            rusqlite::params![node_id],
            |row| row.get(0),
        )
        .optional()?;
    Ok(result)
}

/// Upewnia się, że globalne zasoby core mają domyślne polityki synchronizacji.
pub fn ensure_default_core_sync_policies(pool: &DbPool) -> Result<usize> {
    let conn = acquire(pool)?;
    let mut inserted = 0usize;
    for descriptor in crate::sync::core_registry::CORE_SYNC_DESCRIPTORS {
        let policy_id = format!("policy-core-{}", descriptor.resource_type.replace('.', "-"));
        inserted += conn.execute(
            "INSERT OR IGNORE INTO sync_policies \
             (policy_id, org_id, addon_id, resource_type, resource_id, mode, authority_node_id, retention_days, is_enabled) \
             VALUES (?1, ?2, ?3, ?4, '', 'replicated_by_permission', NULL, NULL, 1)",
            rusqlite::params![
                policy_id,
                crate::services::org::DEFAULT_ORG_ID,
                crate::sync::core_registry::CORE_SYNC_ADDON_ID,
                descriptor.resource_type,
            ],
        )?;
    }
    Ok(inserted)
}

/// Przenosi aktywne zaufanie mesh do identity registry używanego przez sync.
pub fn ensure_trusted_nodes_in_sync_identity(pool: &DbPool) -> Result<usize> {
    let trusted_nodes = list_trusted_nodes(pool)?;
    let conn = acquire(pool)?;
    let mut changed = 0usize;
    for node in trusted_nodes {
        let display_name = if node.hostname.trim().is_empty() {
            node.node_id.as_str()
        } else {
            node.hostname.as_str()
        };
        changed += conn.execute(
            "INSERT INTO sync_nodes \
             (node_id, public_key, public_key_type, display_name, node_kind, trust_status, owner_user_id, sync_profile) \
             VALUES (?1, ?2, 'ed25519', ?3, 'unknown', 'trusted', NULL, 'standard') \
             ON CONFLICT(node_id) DO UPDATE SET \
                 public_key = excluded.public_key, \
                 public_key_type = excluded.public_key_type, \
                 display_name = CASE \
                     WHEN sync_nodes.display_name = '' THEN excluded.display_name \
                     ELSE sync_nodes.display_name \
                 END, \
                 trust_status = 'trusted' \
             WHERE sync_nodes.public_key <> excluded.public_key \
                OR sync_nodes.public_key_type <> excluded.public_key_type \
                OR sync_nodes.trust_status <> 'trusted' \
                OR sync_nodes.display_name = ''",
            rusqlite::params![node.node_id, node.public_key, display_name],
        )?;
    }
    // A newly-trusted node becomes a sync TARGET, but the donor's existing ops were
    // minted before it existed, so the mint-time outbox fan-out never queued them
    // to it and they sit until brand-new activity nudges the outbox. Bumping the
    // permission epoch makes the periodic authority-side backfill
    // (`backfill_outbox_for_permission_grants`) re-evaluate every op against the now-
    // expanded target set and replay the full content backlog to the new node
    // promptly — the same machinery that already backfills permission grants. Only
    // bump when a row actually changed, so a steady-state restart is a no-op.
    if changed > 0 {
        let org_ids: Vec<String> = {
            let mut stmt = conn.prepare("SELECT org_id FROM organizations ORDER BY org_id ASC")?;
            let ids = stmt
                .query_map([], |row| row.get::<_, String>(0))?
                .collect::<std::result::Result<Vec<_>, _>>()?;
            ids
        };
        for org_id in org_ids {
            bump_sync_permission_epoch_with_conn(&conn, &org_id)?;
        }
    }
    Ok(changed)
}

/// Rejestruje lokalny node we własnym rejestrze tożsamości sync. Bez tego wpisu
/// `ensure_local_target_allowed` odrzuca każdy przychodzący push (lokalny node nie
/// jest widziany jako dozwolony target własnych zasobów). Wpis jest czysto lokalny
/// i nie generuje operacji sync — peery weryfikują operacje po node_id (hex klucza
/// ed25519), nie po zsynchronizowanym wierszu sync_nodes. Domyślnie `authority`,
/// bo lokalny node przechowuje wszystko, co jest do niego replikowane. Czysto
/// addytywne: istniejący wiersz (np. skonfigurowany profil) nie jest nadpisywany.
pub fn ensure_local_node_in_sync_identity(
    pool: &DbPool,
    node_id: &str,
    public_key: &str,
) -> Result<()> {
    let conn = acquire(pool)?;
    conn.execute(
        "INSERT OR IGNORE INTO sync_nodes \
         (node_id, public_key, public_key_type, display_name, node_kind, trust_status, owner_user_id, sync_profile) \
         VALUES (?1, ?2, 'ed25519', '', 'server', 'trusted', NULL, 'authority')",
        rusqlite::params![node_id, public_key],
    )?;
    Ok(())
}

// =============================================================================
// Sync Identity Registry — node/device, user keys i przypisania
// =============================================================================

fn row_to_sync_node_identity(row: &rusqlite::Row<'_>) -> rusqlite::Result<SyncNodeIdentity> {
    Ok(SyncNodeIdentity {
        node_id: row.get(0)?,
        public_key: row.get(1)?,
        public_key_type: row.get(2)?,
        display_name: row.get(3)?,
        node_kind: row.get(4)?,
        trust_status: row.get(5)?,
        owner_user_id: row.get(6)?,
        sync_profile: row.get(7)?,
        last_seen_at: row.get(8)?,
        created_at: row.get(9)?,
        updated_at: row.get(10)?,
    })
}

fn row_to_user_identity_key(row: &rusqlite::Row<'_>) -> rusqlite::Result<UserIdentityKey> {
    Ok(UserIdentityKey {
        key_id: row.get(0)?,
        user_id: row.get(1)?,
        key_type: row.get(2)?,
        public_key: row.get(3)?,
        purpose: row.get(4)?,
        status: row.get(5)?,
        created_at: row.get(6)?,
        revoked_at: row.get(7)?,
    })
}

fn row_to_node_user_assignment(row: &rusqlite::Row<'_>) -> rusqlite::Result<NodeUserAssignment> {
    Ok(NodeUserAssignment {
        node_id: row.get(0)?,
        user_id: row.get(1)?,
        assignment_mode: row.get(2)?,
        valid_from: row.get(3)?,
        valid_until: row.get(4)?,
        created_by: row.get(5)?,
        created_at: row.get(6)?,
    })
}

fn row_to_sync_policy(row: &rusqlite::Row<'_>) -> rusqlite::Result<SyncPolicy> {
    let resource_type: String = row.get(3)?;
    let resource_id: String = row.get(4)?;
    let mode: String = row.get(5)?;
    let mode = SyncPolicyMode::parse(&mode).ok_or_else(|| {
        rusqlite::Error::FromSqlConversionFailure(
            5,
            rusqlite::types::Type::Text,
            format!("invalid sync policy mode: {mode}").into(),
        )
    })?;
    Ok(SyncPolicy {
        policy_id: row.get(0)?,
        org_id: row.get(1)?,
        addon_id: row.get(2)?,
        resource_type: (!resource_type.is_empty()).then_some(resource_type),
        resource_id: (!resource_id.is_empty()).then_some(resource_id),
        mode,
        authority_node_id: row.get(6)?,
        retention_days: row.get(7)?,
        is_enabled: row.get(8)?,
        created_at: row.get(9)?,
        updated_at: row.get(10)?,
    })
}

/// Rejestruje albo aktualizuje techniczna tozsamosc node/device.
pub fn upsert_sync_node_identity(
    pool: &DbPool,
    node_id: &str,
    public_key: &str,
    public_key_type: &str,
    display_name: &str,
    node_kind: &str,
    trust_status: &str,
    owner_user_id: Option<&str>,
    sync_profile: &str,
) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    tx.execute(
        "INSERT INTO sync_nodes \
         (node_id, public_key, public_key_type, display_name, node_kind, trust_status, owner_user_id, sync_profile) \
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8) \
         ON CONFLICT(node_id) DO UPDATE SET \
             public_key = excluded.public_key, \
             public_key_type = excluded.public_key_type, \
             display_name = excluded.display_name, \
             node_kind = excluded.node_kind, \
             trust_status = excluded.trust_status, \
             owner_user_id = excluded.owner_user_id, \
             sync_profile = excluded.sync_profile",
        rusqlite::params![
            node_id,
            public_key,
            public_key_type,
            display_name,
            node_kind,
            trust_status,
            owner_user_id,
            sync_profile
        ],
    )?;
    let mut fields = BTreeMap::new();
    fields.insert("public_key".to_string(), field_string(public_key));
    fields.insert("public_key_type".to_string(), field_string(public_key_type));
    fields.insert("display_name".to_string(), field_string(display_name));
    fields.insert("node_kind".to_string(), field_string(node_kind));
    fields.insert("trust_status".to_string(), field_string(trust_status));
    fields.insert(
        "owner_user_id".to_string(),
        field_optional_string(owner_user_id),
    );
    fields.insert("sync_profile".to_string(), field_string(sync_profile));
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::SyncNode,
        node_id,
        crate::sync::runtime::SqlWriteAction::Insert,
        fields,
        owner_user_id.map(|id| id.to_string()),
    )?;
    bump_sync_permission_epoch_with_conn(&tx, crate::services::org::DEFAULT_ORG_ID)?;
    tx.commit()?;
    Ok(())
}

/// Pobiera techniczna tozsamosc node/device.
pub fn get_sync_node_identity(pool: &DbPool, node_id: &str) -> Result<Option<SyncNodeIdentity>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT node_id, public_key, public_key_type, display_name, node_kind, trust_status, \
                owner_user_id, sync_profile, last_seen_at, created_at, updated_at \
         FROM sync_nodes WHERE node_id = ?1",
    )?;
    let result = stmt
        .query_row(rusqlite::params![node_id], row_to_sync_node_identity)
        .optional()?;
    Ok(result)
}

/// Dodaje albo odswieza kryptograficzny klucz uzytkownika.
pub fn upsert_user_identity_key(
    pool: &DbPool,
    key_id: &str,
    user_id: &str,
    key_type: &str,
    public_key: &str,
    purpose: &str,
) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    tx.execute(
        "INSERT INTO user_identity_keys (key_id, user_id, key_type, public_key, purpose, status, revoked_at) \
         VALUES (?1, ?2, ?3, ?4, ?5, 'active', NULL) \
         ON CONFLICT(key_id) DO UPDATE SET \
             user_id = excluded.user_id, \
             key_type = excluded.key_type, \
             public_key = excluded.public_key, \
             purpose = excluded.purpose, \
             status = 'active', \
             revoked_at = NULL",
        rusqlite::params![key_id, user_id, key_type, public_key, purpose],
    )?;
    let mut fields = BTreeMap::new();
    fields.insert("user_id".to_string(), field_string(user_id));
    fields.insert("key_type".to_string(), field_string(key_type));
    fields.insert("public_key".to_string(), field_string(public_key));
    fields.insert("purpose".to_string(), field_string(purpose));
    fields.insert("status".to_string(), field_string("active"));
    fields.insert(
        "revoked_at".to_string(),
        crate::sync::ledger::FieldValue::Null,
    );
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::UserIdentityKey,
        key_id,
        crate::sync::runtime::SqlWriteAction::Insert,
        fields,
        Some(user_id.to_string()),
    )?;
    tx.commit()?;
    Ok(())
}

/// Pobiera aktywne klucze kryptograficzne uzytkownika.
pub fn list_active_user_identity_keys(
    pool: &DbPool,
    user_id: &str,
) -> Result<Vec<UserIdentityKey>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT key_id, user_id, key_type, public_key, purpose, status, created_at, revoked_at \
         FROM user_identity_keys \
         WHERE user_id = ?1 AND status = 'active' \
         ORDER BY created_at DESC",
    )?;
    let rows = stmt
        .query_map(rusqlite::params![user_id], row_to_user_identity_key)?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

/// Revoke klucza uzytkownika bez usuwania historii.
pub fn revoke_user_identity_key(pool: &DbPool, key_id: &str) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    tx.execute(
        "UPDATE user_identity_keys \
         SET status = 'revoked', revoked_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') \
         WHERE key_id = ?1",
        rusqlite::params![key_id],
    )?;
    let mut fields = BTreeMap::new();
    fields.insert("status".to_string(), field_string("revoked"));
    fields.insert(
        "revoked_at".to_string(),
        field_string(&chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string()),
    );
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::UserIdentityKey,
        key_id,
        crate::sync::runtime::SqlWriteAction::Update,
        fields,
        None,
    )?;
    tx.commit()?;
    Ok(())
}

/// Przypisuje uzytkownika do node/device.
pub fn assign_node_to_user(
    pool: &DbPool,
    node_id: &str,
    user_id: &str,
    assignment_mode: &str,
    created_by: Option<&str>,
) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    tx.execute(
        "INSERT INTO node_user_assignments \
         (node_id, user_id, assignment_mode, valid_until, created_by) \
         VALUES (?1, ?2, ?3, NULL, ?4) \
         ON CONFLICT(node_id, user_id, assignment_mode) DO UPDATE SET \
             valid_until = NULL, \
             created_by = excluded.created_by",
        rusqlite::params![node_id, user_id, assignment_mode, created_by],
    )?;
    let mut fields = BTreeMap::new();
    fields.insert("node_id".to_string(), field_string(node_id));
    fields.insert("user_id".to_string(), field_string(user_id));
    fields.insert("assignment_mode".to_string(), field_string(assignment_mode));
    fields.insert("created_by".to_string(), field_optional_string(created_by));
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::NodeUserAssignment,
        node_user_assignment_core_id(node_id, user_id, assignment_mode),
        crate::sync::runtime::SqlWriteAction::Insert,
        fields,
        created_by.map(|id| id.to_string()),
    )?;
    bump_sync_permission_epoch_with_conn(&tx, crate::services::org::DEFAULT_ORG_ID)?;
    tx.commit()?;
    Ok(())
}

/// Konczy aktywne przypisanie uzytkownika do node/device.
pub fn revoke_node_user_assignment(
    pool: &DbPool,
    node_id: &str,
    user_id: &str,
    assignment_mode: &str,
) -> Result<()> {
    let mut conn = acquire(pool)?;
    let tx = conn.transaction()?;
    tx.execute(
        "UPDATE node_user_assignments \
         SET valid_until = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') \
         WHERE node_id = ?1 AND user_id = ?2 AND assignment_mode = ?3 AND valid_until IS NULL",
        rusqlite::params![node_id, user_id, assignment_mode],
    )?;
    let mut fields = BTreeMap::new();
    fields.insert("node_id".to_string(), field_string(node_id));
    fields.insert("user_id".to_string(), field_string(user_id));
    fields.insert("assignment_mode".to_string(), field_string(assignment_mode));
    fields.insert(
        "valid_until".to_string(),
        field_string(&chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string()),
    );
    record_core_capture_tx(
        &tx,
        crate::sync::core_registry::CoreSyncResourceKind::NodeUserAssignment,
        node_user_assignment_core_id(node_id, user_id, assignment_mode),
        crate::sync::runtime::SqlWriteAction::Update,
        fields,
        None,
    )?;
    bump_sync_permission_epoch_with_conn(&tx, crate::services::org::DEFAULT_ORG_ID)?;
    tx.commit()?;
    Ok(())
}

/// Lista aktywnych przypisan danego node/device.
pub fn list_active_node_user_assignments(
    pool: &DbPool,
    node_id: &str,
) -> Result<Vec<NodeUserAssignment>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT node_id, user_id, assignment_mode, valid_from, valid_until, created_by, created_at \
         FROM node_user_assignments \
         WHERE node_id = ?1 AND valid_until IS NULL \
         ORDER BY created_at DESC",
    )?;
    let rows = stmt
        .query_map(rusqlite::params![node_id], row_to_node_user_assignment)?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

/// Lista node/device aktywnie przypisanych do uzytkownika.
pub fn list_sync_nodes_for_user(pool: &DbPool, user_id: &str) -> Result<Vec<SyncNodeIdentity>> {
    let conn = acquire(pool)?;
    let mut stmt = conn.prepare_cached(
        "SELECT n.node_id, n.public_key, n.public_key_type, n.display_name, n.node_kind, \
                n.trust_status, n.owner_user_id, n.sync_profile, n.last_seen_at, \
                n.created_at, n.updated_at \
         FROM sync_nodes n \
         JOIN node_user_assignments a ON a.node_id = n.node_id \
         WHERE a.user_id = ?1 AND a.valid_until IS NULL \
         ORDER BY n.display_name, n.node_id",
    )?;
    let rows = stmt
        .query_map(rusqlite::params![user_id], row_to_sync_node_identity)?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

